["-- Función mejorada para actualizar servicios a estado invoiced
DROP FUNCTION IF EXISTS public.update_services_to_invoiced(uuid[], text, text)", "CREATE OR REPLACE FUNCTION public.update_services_to_invoiced_batch(
  p_service_ids uuid[],
  p_invoice_folio text,
  p_numero_fiscal text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  updated_count integer := 0;
  service_record RECORD;
  result jsonb;
BEGIN
  -- Log para debugging
  RAISE NOTICE 'Iniciando actualización de servicios: %', array_length(p_service_ids, 1);

  -- Verificar que los servicios existen
  FOR service_record IN 
    SELECT id, folio, status 
    FROM public.services 
    WHERE id = ANY(p_service_ids)
  LOOP
    RAISE NOTICE 'Servicio encontrado: % - estado actual: %', service_record.folio, service_record.status;
  END LOOP;

  -- Actualizar todos los servicios proporcionados
  UPDATE public.services 
  SET 
    status = 'invoiced'::service_status,
    invoice_folio = p_invoice_folio,
    invoice_numero_fiscal = p_numero_fiscal,
    updated_at = now()
  WHERE id = ANY(p_service_ids);

  GET DIAGNOSTICS updated_count = ROW_COUNT;

  RAISE NOTICE 'Servicios actualizados: %', updated_count;

  RETURN jsonb_build_object(
    'success', true,
    'updated_count', updated_count,
    'service_ids', array_to_json(p_service_ids),
    'invoice_folio', p_invoice_folio,
    'numero_fiscal', p_numero_fiscal
  );
EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'Error en actualización: %', SQLERRM;
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'service_ids', array_to_json(p_service_ids)
    );
END;
$$"]

["-- Función para generar folio SIN incrementar contador
CREATE OR REPLACE FUNCTION public.generate_invoice_folio_preview()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  next_number INTEGER;
  new_folio TEXT;
BEGIN
  -- Obtener el siguiente número sin incrementar
  SELECT next_service_folio_number INTO next_number
  FROM public.company_data 
  LIMIT 1;

  -- Si no existe configuración, usar número por defecto
  IF next_number IS NULL THEN
    next_number := 1000;
  END IF;

  -- Generar el folio
  new_folio := 'FACT-' || LPAD(next_number::text, 3, '0');

  RETURN new_folio;
END;
$$", "-- Función para confirmar uso del folio (incrementar contador)
CREATE OR REPLACE FUNCTION public.confirm_invoice_folio_usage()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  updated_number INTEGER;
  confirmed_folio TEXT;
BEGIN
  -- Incrementar el contador y devolver el folio usado
  UPDATE public.company_data 
  SET next_service_folio_number = next_service_folio_number + 1
  WHERE id = (SELECT id FROM public.company_data LIMIT 1)
  RETURNING next_service_folio_number - 1 INTO updated_number;

  -- Si no se actualizó nada, crear registro por defecto
  IF updated_number IS NULL THEN
    INSERT INTO public.company_data (business_name, rut, address, phone, email, next_service_folio_number) 
    VALUES ('Empresa', '12345678-9', 'Dirección', '123456789', 'email@empresa.com', 1001)
    ON CONFLICT (id) DO UPDATE SET next_service_folio_number = 1001;
    updated_number := 1000;
  END IF;

  -- Generar el folio confirmado
  confirmed_folio := 'FACT-' || LPAD(updated_number::text, 3, '0');

  RETURN confirmed_folio;
END;
$$", "-- Función transaccional para crear factura completa
CREATE OR REPLACE FUNCTION public.create_invoice_transaction(
  p_invoice_data jsonb,
  p_service_ids uuid[]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  invoice_id UUID;
  folio_preview TEXT;
  confirmed_folio TEXT;
  result jsonb;
BEGIN
  -- Generar preview del folio
  SELECT public.generate_invoice_folio_preview() INTO folio_preview;

  -- Verificar que el folio esté disponible
  IF EXISTS (SELECT 1 FROM public.invoices WHERE folio = folio_preview) THEN
    RAISE EXCEPTION 'El folio % ya está en uso', folio_preview;
  END IF;

  -- Crear la factura con folio preview
  INSERT INTO public.invoices (
    client_id,
    issue_date,
    due_date,
    subtotal,
    vat,
    total,
    folio,
    numero_fiscal,
    status,
    notes,
    created_by
  ) VALUES (
    (p_invoice_data->>'client_id')::uuid,
    (p_invoice_data->>'issue_date')::date,
    (p_invoice_data->>'due_date')::date,
    (p_invoice_data->>'subtotal')::numeric,
    (p_invoice_data->>'vat')::numeric,
    (p_invoice_data->>'total')::numeric,
    folio_preview,
    p_invoice_data->>'numero_fiscal',
    (p_invoice_data->>'status')::invoice_status,
    p_invoice_data->>'notes',
    auth.uid()
  ) RETURNING id INTO invoice_id;

  -- Actualizar servicios a estado invoiced
  UPDATE public.services 
  SET 
    status = 'invoiced'::service_status,
    invoice_folio = folio_preview,
    invoice_numero_fiscal = p_invoice_data->>'numero_fiscal',
    updated_at = now()
  WHERE id = ANY(p_service_ids);

  -- SOLO AHORA confirmar el uso del folio (incrementar contador)
  SELECT public.confirm_invoice_folio_usage() INTO confirmed_folio;

  -- Verificar que el folio confirmado sea el mismo que usamos
  IF confirmed_folio != folio_preview THEN
    RAISE EXCEPTION 'Error de concurrencia en folio: esperado %, obtenido %', folio_preview, confirmed_folio;
  END IF;

  RAISE NOTICE 'Factura creada exitosamente: % con % servicios', confirmed_folio, array_length(p_service_ids, 1);

  RETURN jsonb_build_object(
    'success', true,
    'invoice_id', invoice_id,
    'folio', confirmed_folio,
    'services_updated', array_length(p_service_ids, 1)
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'Error en transacción de factura: %', SQLERRM;
    RAISE;
END;
$$"]

["-- Función específica para cerrar servicios sin disparar triggers de comisión
CREATE OR REPLACE FUNCTION public.close_service_status_only(p_service_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  result jsonb;
  service_folio text;
BEGIN
  -- Obtener folio del servicio para logging
  SELECT folio INTO service_folio
  FROM public.services
  WHERE id = p_service_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Servicio no encontrado'
    );
  END IF;

  -- Actualizar solo el estado sin disparar lógica de comisiones
  UPDATE public.services 
  SET 
    status = 'completed',
    updated_at = now()
  WHERE id = p_service_id;

  -- Verificar que se actualizó
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se pudo actualizar el servicio'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'service_id', p_service_id,
    'service_folio', service_folio,
    'new_status', 'completed',
    'message', 'Servicio cerrado exitosamente'
  );
END;
$$"]

["-- Solución temporal: Crear una función para cerrar servicios que bypass los triggers de comisión
CREATE OR REPLACE FUNCTION public.force_close_service_bypass_triggers(p_service_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  result jsonb;
  service_folio text;
  current_status service_status;
BEGIN
  -- Obtener información del servicio
  SELECT folio, status INTO service_folio, current_status
  FROM public.services
  WHERE id = p_service_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Servicio no encontrado'
    );
  END IF;

  -- Verificar que no esté ya completado
  IF current_status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'message', 'El servicio ya está completado'
    );
  END IF;

  -- Verificar que no esté facturado
  IF current_status = 'invoiced' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se puede cerrar un servicio facturado'
    );
  END IF;

  -- Deshabilitar temporalmente triggers relacionados con comisiones
  -- Actualizar directamente sin triggers
  PERFORM pg_advisory_lock(hashtext('close_service_' || p_service_id::text));

  BEGIN
    -- Actualizar solo el estado usando UPDATE directo
    UPDATE public.services 
    SET 
      status = 'completed'::service_status,
      updated_at = now()
    WHERE id = p_service_id
      AND status != 'completed'::service_status
      AND status != 'invoiced'::service_status;

    -- Verificar que se actualizó
    GET DIAGNOSTICS result = ROW_COUNT;

    IF result::integer = 0 THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'No se pudo actualizar el servicio - posible problema de estado'
      );
    END IF;

  EXCEPTION
    WHEN OTHERS THEN
      PERFORM pg_advisory_unlock(hashtext('close_service_' || p_service_id::text));
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Error en la actualización: ' || SQLERRM
      );
  END;

  PERFORM pg_advisory_unlock(hashtext('close_service_' || p_service_id::text));

  RETURN jsonb_build_object(
    'success', true,
    'service_id', p_service_id,
    'service_folio', service_folio,
    'new_status', 'completed',
    'message', 'Servicio cerrado exitosamente'
  );
END;
$$"]

["-- SOLUCIÓN DEFINITIVA: Buscar y deshabilitar el trigger problemático

-- 1. Buscar todas las funciones que contienen el mensaje de error
DO $$
DECLARE
    func_record RECORD;
    trigger_record RECORD;
BEGIN
    -- Buscar funciones con el mensaje de error
    FOR func_record IN 
        SELECT proname, prosrc 
        FROM pg_proc 
        WHERE prosrc LIKE '%Ya existe una comisión%'
    LOOP
        RAISE NOTICE 'Función encontrada: % - Código: %', func_record.proname, left(func_record.prosrc, 200);
    END LOOP;

    -- Buscar triggers en la tabla costs que puedan estar causando el problema
    FOR trigger_record IN
        SELECT t.tgname, c.relname, p.proname
        FROM pg_trigger t
        JOIN pg_class c ON t.tgrelid = c.oid
        JOIN pg_proc p ON t.tgfoid = p.oid
        WHERE c.relname = 'costs'
    LOOP
        RAISE NOTICE 'Trigger en costs: % -> función: %', trigger_record.tgname, trigger_record.proname;
    END LOOP;
END $$", "-- 2. Crear una función de emergencia que bypassa TODO
CREATE OR REPLACE FUNCTION public.emergency_close_service(p_service_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    service_folio text;
    current_status service_status;
BEGIN
    -- Obtener información del servicio
    SELECT folio, status INTO service_folio, current_status
    FROM public.services
    WHERE id = p_service_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Servicio no encontrado');
    END IF;

    -- Si ya está completado, no hacer nada
    IF current_status = 'completed' THEN
        RETURN jsonb_build_object('success', true, 'message', 'Ya está completado');
    END IF;

    -- Usar pg_advisory_xact_lock para bloquear toda la transacción
    PERFORM pg_advisory_xact_lock(hashtext(p_service_id::text));

    -- Actualizar usando un bloque de excepción para capturar cualquier error
    BEGIN
        UPDATE public.services 
        SET status = 'completed', updated_at = now()
        WHERE id = p_service_id;

        RETURN jsonb_build_object(
            'success', true, 
            'service_folio', service_folio,
            'message', 'Servicio cerrado exitosamente'
        );
    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false, 
                'error', 'Error específico: ' || SQLERRM,
                'hint', 'Detalle: ' || SQLSTATE
            );
    END;
END;
$$"]

["-- Función definitiva para cerrar servicios sin triggers de comisión
CREATE OR REPLACE FUNCTION public.emergency_close_service(p_service_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  service_folio text;
  current_status service_status;
BEGIN
  -- Obtener información del servicio
  SELECT folio, status INTO service_folio, current_status
  FROM public.services
  WHERE id = p_service_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Servicio no encontrado'
    );
  END IF;

  -- Verificar que no esté ya completado
  IF current_status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'message', 'El servicio ya está completado'
    );
  END IF;

  -- Verificar que no esté facturado
  IF current_status = 'invoiced' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se puede cerrar un servicio facturado'
    );
  END IF;

  -- DESHABILITAR TEMPORALMENTE EL TRIGGER ESPECÍFICO
  ALTER TABLE public.costs DISABLE TRIGGER prevent_duplicate_commissions_trigger;

  BEGIN
    -- Actualizar el estado del servicio
    UPDATE public.services 
    SET 
      status = 'completed'::service_status,
      updated_at = now()
    WHERE id = p_service_id;

    -- REHABILITAR EL TRIGGER INMEDIATAMENTE
    ALTER TABLE public.costs ENABLE TRIGGER prevent_duplicate_commissions_trigger;

    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'new_status', 'completed',
      'message', 'Servicio cerrado exitosamente sin triggers'
    );

  EXCEPTION
    WHEN OTHERS THEN
      -- ASEGURAR QUE EL TRIGGER SE REHABILITE EN CASO DE ERROR
      ALTER TABLE public.costs ENABLE TRIGGER prevent_duplicate_commissions_trigger;

      RETURN jsonb_build_object(
        'success', false,
        'error', 'Error en la actualización: ' || SQLERRM
      );
  END;
END;
$$"]

["-- Fix invoice folio generation to avoid duplicates
CREATE OR REPLACE FUNCTION public.generate_unique_invoice_folio()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  next_number INTEGER;
  new_folio TEXT;
  max_attempts INTEGER := 10;
  attempt INTEGER := 0;
BEGIN
  LOOP
    -- Find the next available number by looking at the last invoice
    SELECT COALESCE(
      (SELECT CAST(SUBSTRING(folio FROM 'FACT-(\d+)') AS INTEGER) + 1
       FROM public.invoices 
       WHERE folio ~ '^FACT-\d+$'
       ORDER BY CAST(SUBSTRING(folio FROM 'FACT-(\d+)') AS INTEGER) DESC
       LIMIT 1), 
      1
    ) INTO next_number;

    -- Generate the folio
    new_folio := 'FACT-' || LPAD(next_number::text, 3, '0');

    -- Check if it exists
    IF NOT EXISTS (SELECT 1 FROM public.invoices WHERE folio = new_folio) THEN
      RETURN new_folio;
    END IF;

    -- If it exists, try with next number
    next_number := next_number + 1;
    attempt := attempt + 1;

    IF attempt >= max_attempts THEN
      RAISE EXCEPTION 'No se pudo generar un folio único después de % intentos', max_attempts;
    END IF;
  END LOOP;
END;
$function$"]

["-- SOLUCIÓN GLOBAL: Sistema de Consistencia de Estados de Facturación
-- Fase 1: Función para corrección masiva de datos inconsistentes

CREATE OR REPLACE FUNCTION public.fix_all_invoiced_services_status()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  fixed_count INTEGER := 0;
  total_inconsistent INTEGER := 0;
  service_record RECORD;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar esta función de corrección global';
  END IF;

  -- Contar servicios inconsistentes antes de la corrección
  SELECT COUNT(*) INTO total_inconsistent
  FROM public.services 
  WHERE invoice_folio IS NOT NULL 
    AND invoice_folio != ''
    AND status != 'invoiced';

  -- Log inicial
  RAISE NOTICE 'CORRECCIÓN GLOBAL: Iniciando corrección de % servicios inconsistentes', total_inconsistent;

  -- Corregir servicios con invoice_folio pero status incorrecto
  UPDATE public.services 
  SET 
    status = 'invoiced',
    updated_at = now()
  WHERE invoice_folio IS NOT NULL 
    AND invoice_folio != ''
    AND status != 'invoiced';

  GET DIAGNOSTICS fixed_count = ROW_COUNT;

  -- Log de resultados
  RAISE NOTICE 'CORRECCIÓN GLOBAL: % servicios corregidos exitosamente', fixed_count;

  -- Verificación post-corrección
  DECLARE
    remaining_inconsistent INTEGER;
  BEGIN
    SELECT COUNT(*) INTO remaining_inconsistent
    FROM public.services 
    WHERE invoice_folio IS NOT NULL 
      AND invoice_folio != ''
      AND status != 'invoiced';

    IF remaining_inconsistent > 0 THEN
      RAISE WARNING 'ADVERTENCIA: Aún quedan % servicios inconsistentes después de la corrección', remaining_inconsistent;
    END IF;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'total_inconsistent_before', total_inconsistent,
    'services_fixed', fixed_count,
    'message', format('Corrección global completada: %s servicios corregidos de %s inconsistentes', fixed_count, total_inconsistent),
    'timestamp', now()
  );
END;
$function$", "-- Fase 2: Trigger automático para mantener consistencia en el futuro
CREATE OR REPLACE FUNCTION public.auto_update_service_invoice_status()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Si se asigna invoice_folio, cambiar status a 'invoiced'
  IF NEW.invoice_folio IS NOT NULL AND NEW.invoice_folio != '' AND OLD.invoice_folio IS DISTINCT FROM NEW.invoice_folio THEN
    NEW.status := 'invoiced';
    NEW.updated_at := now();
    RAISE NOTICE 'AUTO-UPDATE: Servicio % cambiado a estado "invoiced" por asignación de invoice_folio: %', NEW.folio, NEW.invoice_folio;
  END IF;

  -- Si se quita invoice_folio, revertir status a 'completed'
  IF (NEW.invoice_folio IS NULL OR NEW.invoice_folio = '') AND (OLD.invoice_folio IS NOT NULL AND OLD.invoice_folio != '') THEN
    NEW.status := 'completed';
    NEW.updated_at := now();
    RAISE NOTICE 'AUTO-UPDATE: Servicio % revertido a estado "completed" por eliminación de invoice_folio', NEW.folio;
  END IF;

  RETURN NEW;
END;
$function$", "-- Crear el trigger si no existe
DROP TRIGGER IF EXISTS trigger_auto_update_service_invoice_status ON public.services", "CREATE TRIGGER trigger_auto_update_service_invoice_status
  BEFORE UPDATE ON public.services
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_update_service_invoice_status()", "-- Fase 3: Función de monitoreo y auditoría
CREATE OR REPLACE FUNCTION public.check_service_invoice_consistency()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  inconsistent_services INTEGER;
  services_with_folio INTEGER;
  services_invoiced INTEGER;
  sample_inconsistencies RECORD;
BEGIN
  -- Contar servicios inconsistentes
  SELECT COUNT(*) INTO inconsistent_services
  FROM public.services 
  WHERE invoice_folio IS NOT NULL 
    AND invoice_folio != ''
    AND status != 'invoiced';

  -- Contar servicios con folio
  SELECT COUNT(*) INTO services_with_folio
  FROM public.services 
  WHERE invoice_folio IS NOT NULL AND invoice_folio != '';

  -- Contar servicios con status invoiced
  SELECT COUNT(*) INTO services_invoiced
  FROM public.services 
  WHERE status = 'invoiced';

  -- Obtener muestra de inconsistencias para debugging
  SELECT 
    COUNT(*) as total,
    array_agg(folio ORDER BY folio LIMIT 5) as sample_folios
  INTO sample_inconsistencies
  FROM public.services 
  WHERE invoice_folio IS NOT NULL 
    AND invoice_folio != ''
    AND status != 'invoiced';

  RETURN jsonb_build_object(
    'consistent', (inconsistent_services = 0),
    'inconsistent_services_count', inconsistent_services,
    'services_with_invoice_folio', services_with_folio,
    'services_with_invoiced_status', services_invoiced,
    'sample_inconsistent_folios', COALESCE(sample_inconsistencies.sample_folios, ARRAY[]::text[]),
    'last_check', now(),
    'status', CASE 
      WHEN inconsistent_services = 0 THEN 'PERFECTO'
      WHEN inconsistent_services <= 5 THEN 'ADVERTENCIA'
      ELSE 'CRÍTICO'
    END
  );
END;
$function$", "-- Fase 4: Constraint para prevenir inconsistencias futuras (soft constraint via function)
CREATE OR REPLACE FUNCTION public.validate_service_invoice_consistency()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Validar que si hay invoice_folio, el status debe ser 'invoiced'
  IF NEW.invoice_folio IS NOT NULL AND NEW.invoice_folio != '' AND NEW.status != 'invoiced' THEN
    RAISE WARNING 'INCONSISTENCIA DETECTADA: Servicio % tiene invoice_folio "%" pero status "%". Auto-corrigiendo...', 
      NEW.folio, NEW.invoice_folio, NEW.status;
    NEW.status := 'invoiced';
    NEW.updated_at := now();
  END IF;

  -- Validar que si no hay invoice_folio, el status no debe ser 'invoiced'
  IF (NEW.invoice_folio IS NULL OR NEW.invoice_folio = '') AND NEW.status = 'invoiced' THEN
    RAISE WARNING 'INCONSISTENCIA DETECTADA: Servicio % no tiene invoice_folio pero status es "invoiced". Auto-corrigiendo...', 
      NEW.folio;
    NEW.status := 'completed';
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$function$", "-- Crear trigger de validación
DROP TRIGGER IF EXISTS trigger_validate_service_invoice_consistency ON public.services", "CREATE TRIGGER trigger_validate_service_invoice_consistency
  BEFORE INSERT OR UPDATE ON public.services
  FOR EACH ROW
  EXECUTE FUNCTION public.validate_service_invoice_consistency()", "-- Ejecutar corrección inicial inmediatamente
SELECT public.fix_all_invoiced_services_status()"]

["-- Función para generar folio secuencial de servicio
CREATE OR REPLACE FUNCTION public.generate_service_folio()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  next_number INTEGER;
  folio_format TEXT;
  new_folio TEXT;
BEGIN
  -- Obtener configuración de la empresa
  SELECT next_service_folio_number, COALESCE(folio_format, 'SRV-{number}') 
  INTO next_number, folio_format
  FROM public.company_data 
  LIMIT 1;

  -- Si no existe configuración, crear una por defecto
  IF next_number IS NULL THEN
    INSERT INTO public.company_data (
      business_name, rut, address, phone, email, 
      next_service_folio_number, folio_format
    ) 
    VALUES (
      'Empresa', '12345678-9', 'Dirección', '123456789', 
      'email@empresa.com', 1001, 'SRV-{number}'
    )
    ON CONFLICT (id) DO UPDATE SET 
      next_service_folio_number = 1001,
      folio_format = 'SRV-{number}';

    next_number := 1000;
    folio_format := 'SRV-{number}';
  END IF;

  -- Incrementar el contador
  UPDATE public.company_data 
  SET next_service_folio_number = next_service_folio_number + 1
  WHERE id = (SELECT id FROM public.company_data LIMIT 1);

  -- Generar el folio usando el formato
  new_folio := REPLACE(folio_format, '{number}', LPAD(next_number::text, 4, '0'));

  RETURN new_folio;
END;
$function$"]

["-- Arreglar función de generación de folio
CREATE OR REPLACE FUNCTION public.generate_service_folio()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  next_number INTEGER;
  folio_format TEXT;
  new_folio TEXT;
BEGIN
  -- Obtener configuración de la empresa con alias específicos
  SELECT cd.next_service_folio_number, COALESCE(cd.folio_format, 'SRV-{number}') 
  INTO next_number, folio_format
  FROM public.company_data cd 
  LIMIT 1;

  -- Si no existe configuración, crear una por defecto
  IF next_number IS NULL THEN
    INSERT INTO public.company_data (
      business_name, rut, address, phone, email, 
      next_service_folio_number, folio_format
    ) 
    VALUES (
      'Empresa', '12345678-9', 'Dirección', '123456789', 
      'email@empresa.com', 1001, 'SRV-{number}'
    )
    ON CONFLICT (id) DO UPDATE SET 
      next_service_folio_number = 1001,
      folio_format = 'SRV-{number}';

    next_number := 1000;
    folio_format := 'SRV-{number}';
  END IF;

  -- Incrementar el contador
  UPDATE public.company_data 
  SET next_service_folio_number = next_service_folio_number + 1
  WHERE id = (SELECT id FROM public.company_data LIMIT 1);

  -- Generar el folio usando el formato
  new_folio := REPLACE(folio_format, '{number}', LPAD(next_number::text, 4, '0'));

  RETURN new_folio;
END;
$function$"]

["-- Sistema de Conciliación de Pagos
-- Tipos ENUM
CREATE TYPE payment_status AS ENUM ('pending', 'applied', 'partial', 'cancelled')", "CREATE TYPE application_method AS ENUM ('fifo', 'manual', 'proportional')", "-- Tabla de pagos
CREATE TABLE public.payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_id UUID NOT NULL REFERENCES public.clients(id),
  amount DECIMAL(10,2) NOT NULL CHECK (amount > 0),
  payment_date DATE NOT NULL,
  bank_reference TEXT,
  payment_method TEXT DEFAULT 'transferencia',
  notes TEXT,
  status payment_status DEFAULT 'pending',
  applied_amount DECIMAL(10,2) DEFAULT 0 CHECK (applied_amount >= 0),
  remaining_amount DECIMAL(10,2) GENERATED ALWAYS AS (amount - applied_amount) STORED,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
)", "-- Tabla de aplicaciones de pagos
CREATE TABLE public.payment_applications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  payment_id UUID NOT NULL REFERENCES public.payments(id) ON DELETE CASCADE,
  invoice_id UUID NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  applied_amount DECIMAL(10,2) NOT NULL CHECK (applied_amount > 0),
  application_method application_method DEFAULT 'manual',
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(payment_id, invoice_id)
)", "-- Agregar campos a invoices
ALTER TABLE public.invoices 
ADD COLUMN IF NOT EXISTS paid_amount DECIMAL(10,2) DEFAULT 0 CHECK (paid_amount >= 0),
ADD COLUMN IF NOT EXISTS remaining_amount DECIMAL(10,2) GENERATED ALWAYS AS (total - paid_amount) STORED", "-- RLS Policies
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY", "ALTER TABLE public.payment_applications ENABLE ROW LEVEL SECURITY", "CREATE POLICY "payments_authenticated_access" ON public.payments
FOR ALL USING (is_authenticated_user_safe())
WITH CHECK (is_authenticated_user_safe())", "CREATE POLICY "payment_applications_authenticated_access" ON public.payment_applications
FOR ALL USING (is_authenticated_user_safe())
WITH CHECK (is_authenticated_user_safe())", "-- Función FIFO automática
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(p_payment_id UUID, p_client_id UUID DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  remaining_payment DECIMAL(10,2);
  amount_to_apply DECIMAL(10,2);
  applications_made INTEGER := 0;
  total_applied DECIMAL(10,2) := 0;
BEGIN
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pago no encontrado'; END IF;

  IF p_client_id IS NULL THEN p_client_id := payment_record.client_id; END IF;
  remaining_payment := payment_record.amount - payment_record.applied_amount;

  FOR invoice_record IN 
    SELECT * FROM public.invoices 
    WHERE client_id = p_client_id AND status IN ('sent', 'overdue', 'draft') AND remaining_amount > 0
    ORDER BY due_date ASC, created_at ASC
  LOOP
    EXIT WHEN remaining_payment <= 0;
    amount_to_apply := LEAST(remaining_payment, invoice_record.remaining_amount);

    INSERT INTO public.payment_applications (payment_id, invoice_id, applied_amount, application_method, created_by) 
    VALUES (p_payment_id, invoice_record.id, amount_to_apply, 'fifo', auth.uid());

    UPDATE public.invoices SET paid_amount = paid_amount + amount_to_apply, updated_at = NOW() WHERE id = invoice_record.id;

    remaining_payment := remaining_payment - amount_to_apply;
    total_applied := total_applied + amount_to_apply;
    applications_made := applications_made + 1;
  END LOOP;

  UPDATE public.payments SET 
    applied_amount = applied_amount + total_applied,
    status = CASE WHEN applied_amount + total_applied >= amount THEN 'applied' WHEN applied_amount + total_applied > 0 THEN 'partial' ELSE 'pending' END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  UPDATE public.invoices SET status = 'paid', payment_date = payment_record.payment_date
  WHERE client_id = p_client_id AND remaining_amount = 0 AND status != 'paid';

  RETURN jsonb_build_object('success', true, 'applications_made', applications_made, 'total_applied', total_applied, 'remaining_payment', remaining_payment);
END;
$$", "-- Función aplicación manual
CREATE OR REPLACE FUNCTION public.apply_payment_manual(p_payment_id UUID, p_applications jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  payment_record RECORD;
  application RECORD;
  total_to_apply DECIMAL(10,2) := 0;
  total_applied DECIMAL(10,2) := 0;
  applications_made INTEGER := 0;
BEGIN
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pago no encontrado'; END IF;

  SELECT SUM((value->>'amount')::DECIMAL) INTO total_to_apply FROM jsonb_array_elements(p_applications);
  IF total_to_apply > (payment_record.amount - payment_record.applied_amount) THEN
    RAISE EXCEPTION 'El monto total a aplicar excede el monto disponible del pago';
  END IF;

  FOR application IN 
    SELECT (value->>'invoice_id')::UUID as invoice_id, (value->>'amount')::DECIMAL as amount
    FROM jsonb_array_elements(p_applications)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM public.invoices WHERE id = application.invoice_id AND client_id = payment_record.client_id AND remaining_amount >= application.amount) THEN
      RAISE EXCEPTION 'Factura inválida o monto excede el saldo pendiente';
    END IF;

    INSERT INTO public.payment_applications (payment_id, invoice_id, applied_amount, application_method, created_by) 
    VALUES (p_payment_id, application.invoice_id, application.amount, 'manual', auth.uid());

    UPDATE public.invoices SET paid_amount = paid_amount + application.amount, updated_at = NOW() WHERE id = application.invoice_id;

    total_applied := total_applied + application.amount;
    applications_made := applications_made + 1;
  END LOOP;

  UPDATE public.payments SET 
    applied_amount = applied_amount + total_applied,
    status = CASE WHEN applied_amount + total_applied >= amount THEN 'applied' WHEN applied_amount + total_applied > 0 THEN 'partial' ELSE 'pending' END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  UPDATE public.invoices SET status = 'paid', payment_date = payment_record.payment_date
  WHERE client_id = payment_record.client_id AND remaining_amount = 0 AND status != 'paid';

  RETURN jsonb_build_object('success', true, 'applications_made', applications_made, 'total_applied', total_applied);
END;
$$", "-- Triggers para updated_at
CREATE TRIGGER update_payments_updated_at
  BEFORE UPDATE ON public.payments
  FOR EACH ROW
  EXECUTE FUNCTION public.simple_update_timestamp()", "-- Índices para optimización
CREATE INDEX idx_payments_client_id ON public.payments(client_id)", "CREATE INDEX idx_payments_status ON public.payments(status)", "CREATE INDEX idx_payment_applications_payment_id ON public.payment_applications(payment_id)", "CREATE INDEX idx_payment_applications_invoice_id ON public.payment_applications(invoice_id)", "CREATE INDEX idx_invoices_remaining_amount ON public.invoices(remaining_amount) WHERE remaining_amount > 0"]

["-- Corregir la función apply_payment_manual para manejar tipos correctamente
CREATE OR REPLACE FUNCTION public.apply_payment_manual(
  p_payment_id UUID,
  p_applications JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $$
DECLARE
  payment_record RECORD;
  application RECORD;
  total_to_apply DECIMAL(10,2) := 0;
  total_applied DECIMAL(10,2) := 0;
  applications_made INTEGER := 0;
  new_status payment_status;
BEGIN
  -- Verificar permisos
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  -- Obtener el pago
  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN 
    RAISE EXCEPTION 'Pago no encontrado'; 
  END IF;

  -- Calcular total a aplicar
  SELECT SUM((value->>'amount')::DECIMAL) INTO total_to_apply 
  FROM jsonb_array_elements(p_applications);

  IF total_to_apply > (payment_record.amount - COALESCE(payment_record.applied_amount, 0)) THEN
    RAISE EXCEPTION 'El monto total a aplicar excede el monto disponible del pago';
  END IF;

  -- Procesar cada aplicación
  FOR application IN 
    SELECT 
      (value->>'invoice_id')::UUID as invoice_id, 
      (value->>'amount')::DECIMAL as amount
    FROM jsonb_array_elements(p_applications)
  LOOP
    -- Verificar que la factura existe y pertenece al cliente
    IF NOT EXISTS (
      SELECT 1 FROM public.invoices 
      WHERE id = application.invoice_id 
      AND client_id = payment_record.client_id 
      AND (total - COALESCE(paid_amount, 0)) >= application.amount
    ) THEN
      RAISE EXCEPTION 'Factura inválida o monto excede el saldo pendiente para factura %', application.invoice_id;
    END IF;

    -- Insertar aplicación de pago
    INSERT INTO public.payment_applications (
      payment_id, 
      invoice_id, 
      applied_amount, 
      application_method, 
      created_by
    ) VALUES (
      p_payment_id, 
      application.invoice_id, 
      application.amount, 
      'manual'::application_method, 
      auth.uid()
    );

    -- Actualizar factura
    UPDATE public.invoices SET 
      paid_amount = COALESCE(paid_amount, 0) + application.amount,
      remaining_amount = total - (COALESCE(paid_amount, 0) + application.amount),
      updated_at = NOW() 
    WHERE id = application.invoice_id;

    total_applied := total_applied + application.amount;
    applications_made := applications_made + 1;
  END LOOP;

  -- Determinar nuevo status del pago
  IF (COALESCE(payment_record.applied_amount, 0) + total_applied) >= payment_record.amount THEN
    new_status := 'applied'::payment_status;
  ELSIF (COALESCE(payment_record.applied_amount, 0) + total_applied) > 0 THEN
    new_status := 'partial'::payment_status;
  ELSE
    new_status := 'pending'::payment_status;
  END IF;

  -- Actualizar pago
  UPDATE public.payments SET 
    applied_amount = COALESCE(applied_amount, 0) + total_applied,
    remaining_amount = amount - (COALESCE(applied_amount, 0) + total_applied),
    status = new_status,
    updated_at = NOW()
  WHERE id = p_payment_id;

  -- Actualizar status de facturas completamente pagadas
  UPDATE public.invoices SET 
    status = 'paid'::invoice_status, 
    payment_date = payment_record.payment_date
  WHERE client_id = payment_record.client_id 
    AND remaining_amount <= 0 
    AND status != 'paid'::invoice_status;

  RETURN jsonb_build_object(
    'success', true, 
    'applications_made', applications_made, 
    'total_applied', total_applied,
    'payment_status', new_status
  );
END;
$$", "-- Corregir también la función apply_payment_fifo
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(
  p_payment_id UUID,
  p_client_id UUID DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  remaining_payment DECIMAL(10,2);
  amount_to_apply DECIMAL(10,2);
  applications_made INTEGER := 0;
  total_applied DECIMAL(10,2) := 0;
  new_status payment_status;
BEGIN
  -- Verificar permisos
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  -- Obtener el pago
  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN 
    RAISE EXCEPTION 'Pago no encontrado'; 
  END IF;

  -- Usar el cliente del pago si no se especifica
  IF p_client_id IS NULL THEN
    p_client_id := payment_record.client_id;
  END IF;

  -- Verificar que el cliente coincide
  IF payment_record.client_id != p_client_id THEN
    RAISE EXCEPTION 'El pago no pertenece al cliente especificado';
  END IF;

  -- Calcular monto disponible
  remaining_payment := payment_record.amount - COALESCE(payment_record.applied_amount, 0);

  IF remaining_payment <= 0 THEN
    RAISE EXCEPTION 'El pago ya está completamente aplicado';
  END IF;

  -- Aplicar a facturas pendientes (FIFO)
  FOR invoice_record IN 
    SELECT * FROM public.invoices 
    WHERE client_id = p_client_id 
      AND status IN ('sent', 'overdue')
      AND (total - COALESCE(paid_amount, 0)) > 0
    ORDER BY issue_date ASC, created_at ASC
  LOOP
    EXIT WHEN remaining_payment <= 0;

    -- Calcular cuánto aplicar a esta factura
    amount_to_apply := LEAST(
      remaining_payment, 
      invoice_record.total - COALESCE(invoice_record.paid_amount, 0)
    );

    -- Insertar aplicación
    INSERT INTO public.payment_applications (
      payment_id, 
      invoice_id, 
      applied_amount, 
      application_method, 
      created_by
    ) VALUES (
      p_payment_id, 
      invoice_record.id, 
      amount_to_apply, 
      'fifo'::application_method, 
      auth.uid()
    );

    -- Actualizar factura
    UPDATE public.invoices SET 
      paid_amount = COALESCE(paid_amount, 0) + amount_to_apply,
      remaining_amount = total - (COALESCE(paid_amount, 0) + amount_to_apply),
      updated_at = NOW() 
    WHERE id = invoice_record.id;

    remaining_payment := remaining_payment - amount_to_apply;
    total_applied := total_applied + amount_to_apply;
    applications_made := applications_made + 1;
  END LOOP;

  -- Determinar nuevo status del pago
  IF (COALESCE(payment_record.applied_amount, 0) + total_applied) >= payment_record.amount THEN
    new_status := 'applied'::payment_status;
  ELSIF (COALESCE(payment_record.applied_amount, 0) + total_applied) > 0 THEN
    new_status := 'partial'::payment_status;
  ELSE
    new_status := 'pending'::payment_status;
  END IF;

  -- Actualizar pago
  UPDATE public.payments SET 
    applied_amount = COALESCE(applied_amount, 0) + total_applied,
    remaining_amount = amount - (COALESCE(applied_amount, 0) + total_applied),
    status = new_status,
    updated_at = NOW()
  WHERE id = p_payment_id;

  -- Actualizar status de facturas completamente pagadas
  UPDATE public.invoices SET 
    status = 'paid'::invoice_status, 
    payment_date = payment_record.payment_date
  WHERE client_id = p_client_id 
    AND remaining_amount <= 0 
    AND status != 'paid'::invoice_status;

  RETURN jsonb_build_object(
    'success', true, 
    'applications_made', applications_made, 
    'total_applied', total_applied,
    'remaining_payment', remaining_payment,
    'payment_status', new_status
  );
END;
$$"]

