["-- Eliminar funciones duplicadas que causan conflictos
DROP FUNCTION IF EXISTS public.create_automatic_payment_for_invoice(uuid, date)", "DROP FUNCTION IF EXISTS public.create_automatic_payment_for_invoice(uuid)", "DROP FUNCTION IF EXISTS public.apply_payment_manual(uuid, jsonb)", "DROP FUNCTION IF EXISTS public.apply_payment_fifo(uuid, uuid)", "-- Recrear función de pago automático (sin tocar remaining_amount generado)
CREATE OR REPLACE FUNCTION public.create_automatic_payment_for_invoice(
    p_invoice_id UUID
) 
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_invoice RECORD;
    v_payment_id UUID;
    v_application_amount DECIMAL;
    result JSON;
BEGIN
    SELECT id, client_id, total, paid_amount, folio, status
    INTO v_invoice
    FROM invoices 
    WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Factura no encontrada: %', p_invoice_id;
    END IF;

    v_application_amount := v_invoice.total - COALESCE(v_invoice.paid_amount, 0);

    IF v_application_amount <= 0 THEN
        RAISE EXCEPTION 'La factura ya está completamente pagada';
    END IF;

    INSERT INTO payments (
        client_id, amount, payment_date, payment_method, bank_reference,
        notes, status, applied_amount, created_by
    ) VALUES (
        v_invoice.client_id, v_application_amount, CURRENT_DATE, 'automatico',
        'PAGO-AUTO-' || v_invoice.folio,
        'Pago automático generado al marcar factura como pagada: ' || v_invoice.folio,
        'applied', v_application_amount, auth.uid()
    ) RETURNING id INTO v_payment_id;

    INSERT INTO payment_applications (
        payment_id, invoice_id, applied_amount, application_method,
        notes, created_at
    ) VALUES (
        v_payment_id, p_invoice_id, v_application_amount, 'manual',
        'Aplicación automática para factura: ' || v_invoice.folio, now()
    );

    UPDATE invoices 
    SET paid_amount = COALESCE(paid_amount, 0) + v_application_amount,
        status = 'paid', payment_date = CURRENT_DATE, updated_at = now()
    WHERE id = p_invoice_id;

    RETURN json_build_object(
        'success', true, 'payment_id', v_payment_id,
        'invoice_id', p_invoice_id, 'amount_paid', v_application_amount
    );
END;
$$", "-- Recrear función de aplicación manual (sin tocar remaining_amount generado)
CREATE OR REPLACE FUNCTION public.apply_payment_manual(
    p_payment_id UUID,
    p_applications JSONB
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_payment RECORD;
    v_application JSONB;
    v_total_applied DECIMAL := 0;
    v_invoice_id UUID;
    v_amount DECIMAL;
BEGIN
    SELECT id, amount, applied_amount FROM payments 
    WHERE id = p_payment_id INTO v_payment;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pago no encontrado';
    END IF;

    FOR v_application IN SELECT * FROM jsonb_array_elements(p_applications)
    LOOP
        v_invoice_id := (v_application->>'invoice_id')::UUID;
        v_amount := (v_application->>'amount')::DECIMAL;
        v_total_applied := v_total_applied + v_amount;

        INSERT INTO payment_applications (
            payment_id, invoice_id, applied_amount, application_method, created_at
        ) VALUES (
            p_payment_id, v_invoice_id, v_amount, 'manual', now()
        );

        UPDATE invoices 
        SET paid_amount = COALESCE(paid_amount, 0) + v_amount,
            status = CASE 
                WHEN (COALESCE(paid_amount, 0) + v_amount) >= total THEN 'paid'
                ELSE status 
            END,
            updated_at = now()
        WHERE id = v_invoice_id;
    END LOOP;

    UPDATE payments 
    SET applied_amount = COALESCE(applied_amount, 0) + v_total_applied,
        status = CASE 
            WHEN (COALESCE(applied_amount, 0) + v_total_applied) >= amount THEN 'applied'
            ELSE 'partial'
        END,
        updated_at = now()
    WHERE id = p_payment_id;

    RETURN json_build_object('success', true, 'total_applied', v_total_applied);
END;
$$", "-- Recrear función FIFO (sin tocar remaining_amount generado)
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(
    p_payment_id UUID,
    p_client_id UUID DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_payment RECORD;
    v_invoice RECORD;
    v_available_amount DECIMAL;
    v_application_amount DECIMAL;
    v_total_applied DECIMAL := 0;
BEGIN
    SELECT id, client_id, amount, applied_amount FROM payments 
    WHERE id = p_payment_id INTO v_payment;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pago no encontrado';
    END IF;

    v_available_amount := v_payment.amount - COALESCE(v_payment.applied_amount, 0);

    FOR v_invoice IN 
        SELECT id, total, paid_amount
        FROM invoices 
        WHERE client_id = COALESCE(p_client_id, v_payment.client_id)
        AND status IN ('sent', 'overdue')
        AND (total - COALESCE(paid_amount, 0)) > 0
        ORDER BY due_date ASC
    LOOP
        EXIT WHEN v_available_amount <= 0;

        v_application_amount := LEAST(
            v_available_amount,
            v_invoice.total - COALESCE(v_invoice.paid_amount, 0)
        );

        INSERT INTO payment_applications (
            payment_id, invoice_id, applied_amount, application_method, created_at
        ) VALUES (
            p_payment_id, v_invoice.id, v_application_amount, 'fifo', now()
        );

        UPDATE invoices 
        SET paid_amount = COALESCE(paid_amount, 0) + v_application_amount,
            status = CASE 
                WHEN (COALESCE(paid_amount, 0) + v_application_amount) >= total THEN 'paid'
                ELSE status 
            END,
            updated_at = now()
        WHERE id = v_invoice.id;

        v_available_amount := v_available_amount - v_application_amount;
        v_total_applied := v_total_applied + v_application_amount;
    END LOOP;

    UPDATE payments 
    SET applied_amount = COALESCE(applied_amount, 0) + v_total_applied,
        status = CASE 
            WHEN (COALESCE(applied_amount, 0) + v_total_applied) >= amount THEN 'applied'
            ELSE 'partial'
        END,
        updated_at = now()
    WHERE id = p_payment_id;

    RETURN json_build_object('success', true, 'total_applied', v_total_applied);
END;
$$"]

["-- CORRECCIÓN COMPLETA DE FOLIOS ÚNICOS DE FACTURAS
-- Eliminar funciones conflictivas de creación de facturas
DROP FUNCTION IF EXISTS public.create_invoice_transaction(uuid, uuid, date, date, numeric, numeric, numeric, text)", "DROP FUNCTION IF EXISTS public.create_invoice_transaction(jsonb, uuid[])", "-- Eliminar generador de folios de facturas problemático
DROP FUNCTION IF EXISTS public.generate_invoice_folio_preview()", "DROP FUNCTION IF EXISTS public.confirm_invoice_folio_usage()", "-- Crear generador de folios únicos para facturas (similar al de servicios)
CREATE OR REPLACE FUNCTION public.generate_unique_invoice_folio()
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  timestamp_part TEXT;
  random_part TEXT;
  candidate_folio TEXT;
  attempts INTEGER := 0;
  max_attempts INTEGER := 10;
BEGIN
  WHILE attempts < max_attempts LOOP
    -- Generar parte timestamp (últimos 6 dígitos de timestamp)
    timestamp_part := (EXTRACT(EPOCH FROM now()) * 1000)::bigint::text;
    timestamp_part := right(timestamp_part, 6);

    -- Generar parte aleatoria (3 dígitos)
    random_part := LPAD((random() * 999)::int::text, 3, '0');

    -- Combinar en formato FACT-XXXXXXYYY
    candidate_folio := 'FACT-' || timestamp_part || random_part;

    -- Verificar uniqueness
    IF NOT EXISTS (SELECT 1 FROM invoices WHERE folio = candidate_folio) THEN
      RETURN candidate_folio;
    END IF;

    attempts := attempts + 1;
    -- Pequeña pausa para evitar colisiones en generación masiva
    PERFORM pg_sleep(0.001);
  END LOOP;

  -- Fallback con UUID si fallan todos los intentos
  RETURN 'FACT-FALLBACK-' || replace(gen_random_uuid()::text, '-', '')::text;
END;
$$", "-- Crear función validadora de folios únicos para facturas
CREATE OR REPLACE FUNCTION public.validate_invoice_folio_uniqueness(folio_to_check TEXT, exclude_invoice_id UUID DEFAULT NULL)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  RETURN NOT EXISTS (
    SELECT 1 FROM invoices 
    WHERE folio = folio_to_check 
    AND (exclude_invoice_id IS NULL OR id != exclude_invoice_id)
  );
END;
$$", "-- Recrear función principal de creación de facturas con folios únicos
CREATE OR REPLACE FUNCTION public.create_invoice_transaction(
  p_invoice_data JSONB,
  p_service_ids UUID[]
)
RETURNS TABLE(invoice_id UUID, invoice_folio TEXT)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  new_invoice_id UUID;
  unique_folio TEXT;
  service_id UUID;
  total_billable_amount NUMERIC := 0;
  service_value NUMERIC;
  client_covered_amount NUMERIC;
BEGIN
  -- Generar folio único
  unique_folio := public.generate_unique_invoice_folio();

  -- Verificar que el folio sea único (doble verificación)
  IF NOT public.validate_invoice_folio_uniqueness(unique_folio) THEN
    RAISE EXCEPTION 'Generated folio % already exists. Please retry.', unique_folio;
  END IF;

  -- Calcular total facturable de servicios
  FOREACH service_id IN ARRAY p_service_ids
  LOOP
    SELECT 
      s.value,
      CASE WHEN s.has_excess THEN s.client_covered_amount ELSE s.value END
    INTO service_value, client_covered_amount
    FROM services s
    WHERE s.id = service_id;

    IF FOUND THEN
      total_billable_amount := total_billable_amount + COALESCE(client_covered_amount, service_value);
    END IF;
  END LOOP;

  -- Crear registro de factura
  INSERT INTO invoices (
    client_id,
    folio,
    issue_date,
    due_date,
    subtotal,
    vat,
    total,
    status,
    notes,
    numero_fiscal,
    created_by
  ) VALUES (
    (p_invoice_data->>'client_id')::UUID,
    unique_folio,
    (p_invoice_data->>'issue_date')::DATE,
    (p_invoice_data->>'due_date')::DATE,
    COALESCE((p_invoice_data->>'subtotal')::NUMERIC, total_billable_amount),
    COALESCE((p_invoice_data->>'vat')::NUMERIC, total_billable_amount * 0.19),
    COALESCE((p_invoice_data->>'total')::NUMERIC, total_billable_amount * 1.19),
    COALESCE(p_invoice_data->>'status', 'draft'),
    p_invoice_data->>'notes',
    p_invoice_data->>'numero_fiscal',
    auth.uid()
  )
  RETURNING id INTO new_invoice_id;

  -- Crear relaciones con servicios
  FOREACH service_id IN ARRAY p_service_ids
  LOOP
    INSERT INTO invoice_services (invoice_id, service_id)
    VALUES (new_invoice_id, service_id);

    -- Actualizar servicios a estado facturado
    UPDATE services 
    SET 
      status = 'invoiced',
      invoice_folio = unique_folio,
      invoice_numero_fiscal = p_invoice_data->>'numero_fiscal',
      updated_at = now()
    WHERE id = service_id;
  END LOOP;

  -- Log exitoso
  RAISE NOTICE 'Invoice created successfully: ID=%, Folio=%', new_invoice_id, unique_folio;

  RETURN QUERY SELECT new_invoice_id, unique_folio;
END;
$$", "-- Crear función para preview de folios (solo para UI)
CREATE OR REPLACE FUNCTION public.preview_next_invoice_folio()
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Solo genera un preview, no reserva el folio
  RETURN 'FACT-' || (EXTRACT(EPOCH FROM now()) * 1000)::bigint::text || '000';
END;
$$"]

