["-- Corregir función del trigger que causa errores al actualizar pagos de proveedores
CREATE OR REPLACE FUNCTION public.create_cost_from_supplier_payment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_category_id UUID;
  cost_description TEXT;
  cost_notes TEXT;
  supplier_name_value TEXT;
BEGIN
  -- Solo procesar cuando el pago cambia a estado "paid"
  IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN

    -- Obtener nombre del proveedor de la tabla suppliers si existe supplier_id
    IF NEW.supplier_id IS NOT NULL THEN
      SELECT name INTO supplier_name_value
      FROM public.suppliers 
      WHERE id = NEW.supplier_id;
    END IF;

    -- Si no se encontró nombre, usar valor por defecto
    IF supplier_name_value IS NULL THEN
      supplier_name_value := 'Proveedor no especificado';
    END IF;

    -- Obtener o crear la categoría "Pagos a Proveedores"
    SELECT id INTO payment_category_id
    FROM public.cost_categories
    WHERE name ILIKE '%pago%proveedor%' OR name ILIKE '%supplier%payment%'
    LIMIT 1;

    -- Si no existe la categoría, crearla
    IF payment_category_id IS NULL THEN
      INSERT INTO public.cost_categories (name, description)
      VALUES ('Pagos a Proveedores', 'Pagos realizados a proveedores y facturas de servicios')
      RETURNING id INTO payment_category_id;
    END IF;

    -- Construir descripción del costo
    cost_description := 'Pago a proveedor: ' || supplier_name_value;
    IF NEW.reference_number IS NOT NULL THEN
      cost_description := cost_description || ' - Referencia: ' || NEW.reference_number;
    END IF;

    -- Construir notas del costo
    cost_notes := 'Pago generado automáticamente desde proveedor.';
    IF NEW.description IS NOT NULL THEN
      cost_notes := cost_notes || ' Descripción: ' || NEW.description;
    END IF;
    IF NEW.notes IS NOT NULL THEN
      cost_notes := cost_notes || ' Notas: ' || NEW.notes;
    END IF;

    -- Crear registro en costos
    INSERT INTO public.costs (
      amount,
      category_id,
      date,
      description,
      notes,
      subcategory,
      supplier_payment_id,
      created_by
    ) VALUES (
      COALESCE(NEW.amount, 0),
      payment_category_id,
      COALESCE(NEW.paid_date, NEW.due_date, CURRENT_DATE),
      cost_description,
      cost_notes,
      CASE 
        WHEN NEW.category ILIKE '%combustible%' OR NEW.category ILIKE '%gasolina%' OR NEW.category ILIKE '%diesel%' THEN 'Combustible'
        WHEN NEW.category ILIKE '%mantenimiento%' OR NEW.category ILIKE '%reparaci%' OR NEW.category ILIKE '%repuesto%' THEN 'Mantenimiento'
        WHEN NEW.category ILIKE '%seguro%' OR NEW.category ILIKE '%insurance%' THEN 'Seguros'
        WHEN NEW.category ILIKE '%administrat%' OR NEW.category ILIKE '%oficina%' THEN 'Administrativo'
        ELSE COALESCE(NEW.category, 'General')
      END,
      NEW.id,
      COALESCE(NEW.created_by, auth.uid())
    );

    RAISE NOTICE 'Costo creado automáticamente para pago de proveedor: %', NEW.id;
  END IF;

  -- Si el pago se despaga (cambia de paid a otro estado), eliminar el costo asociado
  IF OLD.status = 'paid' AND NEW.status != 'paid' THEN
    DELETE FROM public.costs WHERE supplier_payment_id = NEW.id;
    RAISE NOTICE 'Costo eliminado automáticamente para pago despagado: %', NEW.id;
  END IF;

  RETURN NEW;
END;
$function$"]

["-- Mejorar la función emergency_close_service para manejar conflictos de índices únicos
CREATE OR REPLACE FUNCTION public.emergency_close_service(p_service_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  service_folio text;
  current_status service_status;
  existing_costs_count integer;
BEGIN
  -- Obtener información del servicio
  SELECT folio, status INTO service_folio, current_status
  FROM public.services
  WHERE id = p_service_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Servicio no encontrado'
    );
  END IF;

  -- Verificar que no esté ya completado
  IF current_status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'message', 'El servicio ya está completado'
    );
  END IF;

  -- Verificar que no esté facturado
  IF current_status = 'invoiced' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se puede cerrar un servicio facturado'
    );
  END IF;

  -- Verificar si ya existen costos para este servicio
  SELECT COUNT(*) INTO existing_costs_count
  FROM public.costs
  WHERE service_id = p_service_id;

  -- Si ya existen costos, solo actualizar el estado sin crear nuevos costos
  IF existing_costs_count > 0 THEN
    UPDATE public.services 
    SET 
      status = 'completed'::service_status,
      updated_at = now()
    WHERE id = p_service_id;

    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'new_status', 'completed',
      'message', 'Servicio cerrado exitosamente (costos existentes preservados)',
      'existing_costs', existing_costs_count
    );
  END IF;

  -- DESHABILITAR TEMPORALMENTE TODOS LOS TRIGGERS RELACIONADOS
  ALTER TABLE public.costs DISABLE TRIGGER ALL;
  ALTER TABLE public.services DISABLE TRIGGER ALL;

  BEGIN
    -- Actualizar el estado del servicio
    UPDATE public.services 
    SET 
      status = 'completed'::service_status,
      updated_at = now()
    WHERE id = p_service_id;

    -- REHABILITAR TODOS LOS TRIGGERS INMEDIATAMENTE
    ALTER TABLE public.costs ENABLE TRIGGER ALL;
    ALTER TABLE public.services ENABLE TRIGGER ALL;

    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'new_status', 'completed',
      'message', 'Servicio cerrado exitosamente sin triggers'
    );

  EXCEPTION
    WHEN unique_violation THEN
      -- REHABILITAR TRIGGERS EN CASO DE ERROR DE CLAVE ÚNICA
      ALTER TABLE public.costs ENABLE TRIGGER ALL;
      ALTER TABLE public.services ENABLE TRIGGER ALL;

      -- Solo actualizar el estado del servicio sin crear costos duplicados
      UPDATE public.services 
      SET 
        status = 'completed'::service_status,
        updated_at = now()
      WHERE id = p_service_id;

      RETURN jsonb_build_object(
        'success', true,
        'service_id', p_service_id,
        'service_folio', service_folio,
        'new_status', 'completed',
        'message', 'Servicio cerrado exitosamente (evitando duplicados)'
      );

    WHEN OTHERS THEN
      -- ASEGURAR QUE TODOS LOS TRIGGERS SE REHABILITEN EN CASO DE CUALQUIER ERROR
      ALTER TABLE public.costs ENABLE TRIGGER ALL;
      ALTER TABLE public.services ENABLE TRIGGER ALL;

      RETURN jsonb_build_object(
        'success', false,
        'error', 'Error en la actualización: ' || SQLERRM,
        'error_code', SQLSTATE
      );
  END;
END;
$$"]

["-- Fix duplicate commissions issue by simplifying emergency_close_service
-- This migration removes commission creation logic from emergency_close_service
-- The existing trigger generate_commission_on_service_completion_trigger will handle commission creation

CREATE OR REPLACE FUNCTION public.emergency_close_service(p_service_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  service_folio text;
  current_status service_status;
  existing_costs_count integer;
  existing_commissions_count integer;
  commission_category_id uuid;
BEGIN
  -- Obtener información del servicio
  SELECT folio, status INTO service_folio, current_status
  FROM public.services
  WHERE id = p_service_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Servicio no encontrado'
    );
  END IF;

  -- Verificar que no esté ya completado
  IF current_status = 'completed' THEN
    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'message', 'El servicio ya está completado'
    );
  END IF;

  -- Verificar que no esté facturado
  IF current_status = 'invoiced' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se puede cerrar un servicio facturado'
    );
  END IF;

  -- Obtener ID de categoría de comisiones para información
  SELECT id INTO commission_category_id
  FROM public.cost_categories 
  WHERE name ILIKE '%comisi%' 
  LIMIT 1;

  -- Contar costos existentes solo para información
  SELECT COUNT(*) INTO existing_costs_count
  FROM public.costs
  WHERE service_id = p_service_id;

  -- Contar comisiones existentes solo para información
  SELECT COUNT(*) INTO existing_commissions_count
  FROM public.costs
  WHERE service_id = p_service_id 
    AND category_id = commission_category_id;

  -- SOLUCIÓN SIMPLIFICADA: Solo actualizar el estado del servicio
  -- El trigger generate_commission_on_service_completion_trigger se encargará de crear las comisiones automáticamente
  BEGIN
    UPDATE public.services 
    SET 
      status = 'completed'::service_status,
      updated_at = now()
    WHERE id = p_service_id;

    -- Verificar que la actualización fue exitosa
    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'No se pudo actualizar el servicio'
      );
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'service_id', p_service_id,
      'service_folio', service_folio,
      'new_status', 'completed',
      'message', 'Servicio cerrado exitosamente - comisiones creadas automáticamente por trigger',
      'existing_costs_before', existing_costs_count,
      'existing_commissions_before', existing_commissions_count,
      'note', 'Las comisiones son manejadas automáticamente por el trigger del sistema'
    );

  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Error al cerrar servicio: ' || SQLERRM,
        'error_code', SQLSTATE,
        'service_id', p_service_id,
        'service_folio', service_folio
      );
  END;
END;
$function$"]

["-- Corrección completa del sistema de reconciliación de pagos
-- Problema: Las columnas remaining_amount son generadas y no pueden actualizarse manualmente

-- 1. Primero agregar 'partial' al enum de invoice_status si no existe
DO $$ 
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_enum WHERE enumlabel = 'partial' AND enumtypid = 'invoice_status'::regtype) THEN
        ALTER TYPE invoice_status ADD VALUE 'partial';
    END IF;
END $$", "-- 2. Eliminar y recrear función apply_payment_manual
DROP FUNCTION IF EXISTS public.apply_payment_manual(uuid, jsonb)", "CREATE FUNCTION public.apply_payment_manual(
  p_payment_id uuid,
  p_applications jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_amount numeric;
  total_applied numeric := 0;
  application jsonb;
  invoice_total numeric;
  current_paid numeric;
  new_applied numeric;
  result_applications jsonb := '[]'::jsonb;
BEGIN
  -- Validar que el pago existe y obtener su monto
  SELECT amount INTO payment_amount
  FROM payments 
  WHERE id = p_payment_id;

  IF payment_amount IS NULL THEN
    RAISE EXCEPTION 'Pago no encontrado: %', p_payment_id;
  END IF;

  -- Procesar cada aplicación
  FOR application IN SELECT * FROM jsonb_array_elements(p_applications)
  LOOP
    DECLARE
      app_invoice_id uuid := (application->>'invoice_id')::uuid;
      app_amount numeric := (application->>'amount')::numeric;
    BEGIN
      -- Validar monto de aplicación
      IF app_amount <= 0 THEN
        RAISE EXCEPTION 'El monto de aplicación debe ser mayor a 0';
      END IF;

      total_applied := total_applied + app_amount;

      -- Validar que no exceda el monto del pago
      IF total_applied > payment_amount THEN
        RAISE EXCEPTION 'El total aplicado (%) excede el monto del pago (%)', total_applied, payment_amount;
      END IF;

      -- Obtener información de la factura
      SELECT total, COALESCE(paid_amount, 0) 
      INTO invoice_total, current_paid
      FROM invoices 
      WHERE id = app_invoice_id;

      IF invoice_total IS NULL THEN
        RAISE EXCEPTION 'Factura no encontrada: %', app_invoice_id;
      END IF;

      -- Validar que la aplicación no exceda lo pendiente
      IF current_paid + app_amount > invoice_total THEN
        RAISE EXCEPTION 'La aplicación excede el monto pendiente de la factura';
      END IF;

      -- Crear aplicación de pago
      INSERT INTO payment_applications (
        payment_id, invoice_id, applied_amount, application_method, 
        notes, created_by
      ) VALUES (
        p_payment_id, app_invoice_id, app_amount, 'manual',
        'Aplicación manual de pago', auth.uid()
      );

      -- Actualizar factura (sin tocar remaining_amount)
      new_applied := current_paid + app_amount;
      UPDATE invoices 
      SET 
        paid_amount = new_applied,
        status = CASE 
          WHEN new_applied >= invoice_total THEN 'paid'::invoice_status
          WHEN new_applied > 0 THEN 'partial'::invoice_status
          ELSE status
        END,
        payment_date = CASE 
          WHEN new_applied >= invoice_total THEN CURRENT_DATE
          ELSE payment_date
        END,
        updated_at = NOW()
      WHERE id = app_invoice_id;

      -- Agregar al resultado
      result_applications := result_applications || jsonb_build_object(
        'invoice_id', app_invoice_id,
        'applied_amount', app_amount
      );
    END;
  END LOOP;

  -- Actualizar pago (sin tocar remaining_amount)
  UPDATE payments 
  SET 
    applied_amount = total_applied,
    status = CASE 
      WHEN total_applied >= payment_amount THEN 'applied'::payment_status
      WHEN total_applied > 0 THEN 'partial'::payment_status
      ELSE 'pending'::payment_status
    END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'total_applied', total_applied,
    'applications', result_applications
  );
END;
$function$", "-- 3. Eliminar y recrear función apply_payment_fifo
DROP FUNCTION IF EXISTS public.apply_payment_fifo(uuid, uuid)", "CREATE FUNCTION public.apply_payment_fifo(
  p_payment_id uuid,
  p_client_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_amount numeric;
  payment_applied numeric;
  remaining_to_apply numeric;
  invoice_record record;
  applied_to_invoice numeric;
  applications_count integer := 0;
BEGIN
  -- Obtener información del pago
  SELECT amount, COALESCE(applied_amount, 0)
  INTO payment_amount, payment_applied
  FROM payments 
  WHERE id = p_payment_id AND client_id = p_client_id;

  IF payment_amount IS NULL THEN
    RAISE EXCEPTION 'Pago no encontrado';
  END IF;

  remaining_to_apply := payment_amount - payment_applied;

  IF remaining_to_apply <= 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'El pago ya está completamente aplicado',
      'applications_created', 0
    );
  END IF;

  -- Aplicar a facturas pendientes por orden FIFO
  FOR invoice_record IN 
    SELECT id, folio, total, COALESCE(paid_amount, 0) as paid_amount
    FROM invoices 
    WHERE client_id = p_client_id 
    AND status IN ('sent', 'partial', 'overdue')
    AND total > COALESCE(paid_amount, 0)
    ORDER BY issue_date ASC, created_at ASC
  LOOP
    -- Calcular cuánto aplicar a esta factura
    applied_to_invoice := LEAST(
      remaining_to_apply, 
      invoice_record.total - invoice_record.paid_amount
    );

    -- Crear aplicación
    INSERT INTO payment_applications (
      payment_id, invoice_id, applied_amount, application_method,
      notes, created_by
    ) VALUES (
      p_payment_id, invoice_record.id, applied_to_invoice, 'fifo',
      'Aplicación automática FIFO', auth.uid()
    );

    -- Actualizar factura (sin tocar remaining_amount)
    UPDATE invoices 
    SET 
      paid_amount = invoice_record.paid_amount + applied_to_invoice,
      status = CASE 
        WHEN invoice_record.paid_amount + applied_to_invoice >= invoice_record.total 
        THEN 'paid'::invoice_status
        ELSE 'partial'::invoice_status
      END,
      payment_date = CASE 
        WHEN invoice_record.paid_amount + applied_to_invoice >= invoice_record.total 
        THEN CURRENT_DATE
        ELSE payment_date
      END,
      updated_at = NOW()
    WHERE id = invoice_record.id;

    remaining_to_apply := remaining_to_apply - applied_to_invoice;
    applications_count := applications_count + 1;

    EXIT WHEN remaining_to_apply <= 0;
  END LOOP;

  -- Actualizar pago (sin tocar remaining_amount)
  UPDATE payments 
  SET 
    applied_amount = payment_amount - remaining_to_apply,
    status = CASE 
      WHEN remaining_to_apply <= 0 THEN 'applied'::payment_status
      WHEN payment_amount - remaining_to_apply > 0 THEN 'partial'::payment_status
      ELSE 'pending'::payment_status
    END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'applications_created', applications_count,
    'amount_applied', payment_amount - remaining_to_apply,
    'remaining_amount', remaining_to_apply
  );
END;
$function$"]

["-- Modificar el trigger create_cost_from_supplier_payment para evitar duplicados
-- cuando ya existe un costo para el supplier_payment_id

CREATE OR REPLACE FUNCTION public.create_cost_from_supplier_payment()
RETURNS TRIGGER AS $$
DECLARE
  payment_category_id UUID;
  cost_description TEXT;
  cost_notes TEXT;
  supplier_name_value TEXT;
  existing_cost_count INTEGER;
BEGIN
  -- Solo procesar cuando el pago cambia a estado "paid"
  IF NEW.status = 'paid' AND (OLD.status IS NULL OR OLD.status != 'paid') THEN

    -- Verificar si ya existe un costo para este pago (evitar duplicados)
    SELECT COUNT(*) INTO existing_cost_count
    FROM public.costs
    WHERE supplier_payment_id = NEW.id;

    -- Si ya existe un costo, no crear otro
    IF existing_cost_count > 0 THEN
      RETURN NEW;
    END IF;

    -- Obtener nombre del proveedor de la tabla suppliers si existe supplier_id
    IF NEW.supplier_id IS NOT NULL THEN
      SELECT name INTO supplier_name_value
      FROM public.suppliers 
      WHERE id = NEW.supplier_id;
    END IF;

    -- Si no se encontró nombre, usar valor por defecto
    IF supplier_name_value IS NULL THEN
      supplier_name_value := 'Proveedor no especificado';
    END IF;

    -- Obtener o crear la categoría "Pagos a Proveedores"
    SELECT id INTO payment_category_id
    FROM public.cost_categories
    WHERE name ILIKE '%pago%proveedor%' OR name ILIKE '%supplier%payment%'
    LIMIT 1;

    -- Si no existe la categoría, crearla
    IF payment_category_id IS NULL THEN
      INSERT INTO public.cost_categories (name, description)
      VALUES ('Pagos a Proveedores', 'Pagos realizados a proveedores y facturas de servicios')
      RETURNING id INTO payment_category_id;
    END IF;

    -- Construir descripción del costo
    cost_description := 'Pago a proveedor: ' || supplier_name_value;
    IF NEW.reference_number IS NOT NULL THEN
      cost_description := cost_description || ' - Referencia: ' || NEW.reference_number;
    END IF;

    -- Construir notas del costo
    cost_notes := 'Pago generado automáticamente desde proveedor.';
    IF NEW.description IS NOT NULL THEN
      cost_notes := cost_notes || ' Descripción: ' || NEW.description;
    END IF;
    IF NEW.notes IS NOT NULL THEN
      cost_notes := cost_notes || ' Notas: ' || NEW.notes;
    END IF;

    -- Crear registro en costos solo si no existe uno previo
    INSERT INTO public.costs (
      amount,
      category_id,
      date,
      description,
      notes,
      subcategory,
      supplier_payment_id,
      created_by
    ) VALUES (
      COALESCE(NEW.amount, 0),
      payment_category_id,
      COALESCE(NEW.paid_date, CURRENT_DATE),
      cost_description,
      cost_notes,
      CASE 
        WHEN NEW.category ILIKE '%combustible%' OR NEW.category ILIKE '%gasolina%' OR NEW.category ILIKE '%diesel%' THEN 'Combustible'
        WHEN NEW.category ILIKE '%mantenimiento%' OR NEW.category ILIKE '%reparaci%' OR NEW.category ILIKE '%repuesto%' THEN 'Mantenimiento General'
        WHEN NEW.category ILIKE '%seguro%' OR NEW.category ILIKE '%insurance%' THEN 'Seguros'
        WHEN NEW.category ILIKE '%administrat%' OR NEW.category ILIKE '%oficina%' THEN 'Administrativo'
        ELSE NEW.category
      END,
      NEW.id,
      NEW.created_by
    );
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql"]

["-- Corregir la función calculate_billing_date para usar días, no meses
CREATE OR REPLACE FUNCTION public.calculate_billing_date(service_date date, billing_cycle_type text, billing_delay_days integer DEFAULT 0, billing_cycle_day integer DEFAULT NULL::integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  service_month_start date;
  next_month date;
  billing_date date;
BEGIN
  IF billing_cycle_type = 'immediate' THEN
    RETURN service_date;
  END IF;

  -- Para facturación diferida, todos los servicios de un mes se facturan en el mes siguiente
  -- Calcular el primer día del mes del servicio
  service_month_start := date_trunc('month', service_date)::date;

  -- Calcular el mes siguiente más los DÍAS de diferimiento
  next_month := (service_month_start + interval '1 month' + (billing_delay_days || ' days')::interval)::date;

  -- Si se especifica un día del ciclo, usar ese día, sino usar el día 5
  IF billing_cycle_day IS NOT NULL AND billing_cycle_day BETWEEN 1 AND 28 THEN
    -- Ajustar al día específico del mes
    billing_date := date_trunc('month', next_month)::date + (billing_cycle_day - 1);
  ELSE
    -- Por defecto usar el día 5 del mes
    billing_date := date_trunc('month', next_month)::date + interval '4 days';
  END IF;

  RETURN billing_date;
END;
$function$"]

["-- Función para recalcular automáticamente el estado de una factura
CREATE OR REPLACE FUNCTION public.auto_update_invoice_status()
RETURNS TRIGGER AS $$
DECLARE
  v_invoice_id UUID;
  v_invoice_total NUMERIC;
  v_invoice_due_date DATE;
  v_total_applied NUMERIC;
  v_new_status invoice_status;
BEGIN
  -- Determinar el invoice_id según el tipo de operación
  IF TG_OP = 'DELETE' THEN
    v_invoice_id := OLD.invoice_id;
  ELSE
    v_invoice_id := NEW.invoice_id;
  END IF;

  -- Obtener información de la factura
  SELECT total, due_date INTO v_invoice_total, v_invoice_due_date
  FROM invoices 
  WHERE id = v_invoice_id;

  -- Calcular total aplicado
  SELECT COALESCE(SUM(applied_amount), 0) INTO v_total_applied
  FROM payment_applications 
  WHERE invoice_id = v_invoice_id;

  -- Determinar nuevo estado
  IF v_total_applied >= v_invoice_total THEN
    v_new_status := 'paid'::invoice_status;
  ELSIF v_total_applied > 0 THEN
    v_new_status := 'partial'::invoice_status;
  ELSIF v_invoice_due_date < CURRENT_DATE THEN
    v_new_status := 'overdue'::invoice_status;
  ELSE
    v_new_status := 'sent'::invoice_status;
  END IF;

  -- Actualizar la factura (sin tocar campos generados automáticamente)
  UPDATE invoices 
  SET 
    paid_amount = v_total_applied,
    status = v_new_status,
    payment_date = CASE 
      WHEN v_new_status = 'paid' AND payment_date IS NULL THEN CURRENT_DATE
      WHEN v_new_status != 'paid' THEN NULL
      ELSE payment_date
    END,
    updated_at = NOW()
  WHERE id = v_invoice_id;

  -- Log para debugging
  RAISE NOTICE 'Auto-updated invoice %: total_applied=%, status=%', v_invoice_id, v_total_applied, v_new_status;

  -- Retornar registro apropiado según la operación
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public", "-- Crear trigger que se ejecuta automáticamente en cambios de payment_applications
DROP TRIGGER IF EXISTS payment_applications_auto_update_invoice_status ON payment_applications", "CREATE TRIGGER payment_applications_auto_update_invoice_status
  AFTER INSERT OR UPDATE OR DELETE ON payment_applications
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_update_invoice_status()", "-- Función de mantenimiento para corrección masiva (mejorada)
CREATE OR REPLACE FUNCTION public.fix_all_invoice_statuses()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $$
DECLARE
  invoice_record RECORD;
  fixed_count INTEGER := 0;
  total_applied NUMERIC;
  new_status invoice_status;
  old_status invoice_status;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar correcciones masivas';
  END IF;

  -- Procesar todas las facturas
  FOR invoice_record IN 
    SELECT 
      i.id,
      i.folio,
      i.total,
      i.due_date,
      i.status as current_status,
      COALESCE(SUM(pa.applied_amount), 0) as calculated_paid_amount
    FROM invoices i
    LEFT JOIN payment_applications pa ON i.id = pa.invoice_id
    GROUP BY i.id, i.folio, i.total, i.due_date, i.status
  LOOP
    total_applied := invoice_record.calculated_paid_amount;
    old_status := invoice_record.current_status;

    -- Determinar estado correcto
    IF total_applied >= invoice_record.total THEN
      new_status := 'paid'::invoice_status;
    ELSIF total_applied > 0 THEN
      new_status := 'partial'::invoice_status;
    ELSIF invoice_record.due_date < CURRENT_DATE THEN
      new_status := 'overdue'::invoice_status;
    ELSE
      new_status := 'sent'::invoice_status;
    END IF;

    -- Actualizar solo si hay cambios
    IF old_status != new_status OR ABS(COALESCE((SELECT paid_amount FROM invoices WHERE id = invoice_record.id), 0) - total_applied) > 0.01 THEN
      UPDATE invoices 
      SET 
        paid_amount = total_applied,
        status = new_status,
        payment_date = CASE 
          WHEN new_status = 'paid' AND payment_date IS NULL THEN CURRENT_DATE
          WHEN new_status != 'paid' THEN NULL
          ELSE payment_date
        END,
        updated_at = NOW()
      WHERE id = invoice_record.id;

      fixed_count := fixed_count + 1;

      RAISE NOTICE 'Corregida factura %: % -> %, paid_amount: %', 
        invoice_record.folio, old_status, new_status, total_applied;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'fixed_invoices', fixed_count,
    'message', format('Corregidas %s facturas con estados inconsistentes', fixed_count),
    'timestamp', NOW()
  );
END;
$$"]

["-- =====================================================
-- SOLUCIÓN COMPLETA PARA PROBLEMAS DE INVENTARIO
-- =====================================================

-- 1. ACTUALIZAR FUNCIÓN sync_inventory_exit_to_crane_parts()
-- Corregir costos y eliminar duplicación de registros
CREATE OR REPLACE FUNCTION public.sync_inventory_exit_to_crane_parts()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  item_name TEXT;
  item_unit_cost NUMERIC;
  fallback_unit_cost NUMERIC;
  final_unit_cost NUMERIC;
  safe_quantity INTEGER;
  existing_manual_record_count INTEGER;
BEGIN
  -- Solo procesar movimientos de salida con crane_id
  IF NEW.movement_type = 'exit' AND NEW.crane_id IS NOT NULL THEN

    -- Obtener nombre y costo del item desde inventory_items
    SELECT name, unit_cost INTO item_name, item_unit_cost
    FROM public.inventory_items 
    WHERE id = NEW.item_id;

    -- Verificar si ya existe un registro manual
    SELECT COUNT(*) INTO existing_manual_record_count
    FROM public.crane_parts
    WHERE crane_id = NEW.crane_id
    AND LOWER(TRIM(part_name)) = LOWER(TRIM(COALESCE(item_name, 'Item desconocido')))
    AND date = NEW.movement_date::date
    AND inventory_movement_id IS NULL;

    -- Si ya existe un registro manual, no crear automático
    IF existing_manual_record_count > 0 THEN
      RAISE NOTICE 'Ya existe registro manual para % en grúa % fecha %', item_name, NEW.crane_id, NEW.movement_date::date;
      RETURN NEW;
    END IF;

    -- Determinar el costo unitario a usar
    IF item_unit_cost IS NOT NULL AND item_unit_cost > 0 THEN
      final_unit_cost := item_unit_cost;
      RAISE NOTICE 'Usando costo de catálogo: $% para %', final_unit_cost, item_name;
    ELSE
      -- Fallback: buscar promedio de costos históricos de entrada
      SELECT AVG(unit_cost) INTO fallback_unit_cost
      FROM public.inventory_movements 
      WHERE item_id = NEW.item_id 
        AND movement_type IN ('entry', 'purchase')
        AND unit_cost > 0
        AND unit_cost IS NOT NULL;

      IF fallback_unit_cost IS NOT NULL AND fallback_unit_cost > 0 THEN
        final_unit_cost := fallback_unit_cost;
        RAISE NOTICE 'Usando costo promedio histórico: $% para %', final_unit_cost, item_name;
      ELSE
        -- Último recurso: usar $0.01 pero generar advertencia
        final_unit_cost := 0.01;
        RAISE WARNING 'ATENCIÓN: No se encontró costo para %. Usando $0.01 como último recurso. Revisar inventory_items.unit_cost', item_name;
      END IF;
    END IF;

    -- Asegurar valores válidos
    safe_quantity := COALESCE(ABS(NEW.quantity), 1);

    -- IMPORTANTE: NO CREAR REGISTRO EN COSTS
    -- Solo crear registro en crane_parts para trazabilidad
    INSERT INTO public.crane_parts (
      crane_id,
      part_name,
      date,
      quantity,
      unit_price,
      supplier,
      notes,
      cost_id,           -- NULL - no vincular a cost
      inventory_movement_id,
      created_by
    ) VALUES (
      NEW.crane_id,
      COALESCE(item_name, 'Item desconocido'),
      NEW.movement_date::date,
      -safe_quantity, -- Cantidad negativa para consumo
      final_unit_cost, -- Usar el costo real calculado
      COALESCE(NEW.supplier_name, 'Inventario interno'),
      format('Consumo automático desde inventario. Costo: $%s (fuente: %s)', 
        final_unit_cost, 
        CASE 
          WHEN item_unit_cost IS NOT NULL AND item_unit_cost > 0 THEN 'catálogo'
          WHEN fallback_unit_cost IS NOT NULL AND fallback_unit_cost > 0 THEN 'promedio histórico'
          ELSE 'valor por defecto'
        END
      ),
      NULL, -- No crear cost asociado
      NEW.id,
      COALESCE(NEW.created_by, auth.uid())
    );

    RAISE NOTICE 'Registro de consumo creado para %: $% x % = $%', 
      item_name, final_unit_cost, safe_quantity, (final_unit_cost * safe_quantity);
  END IF;

  RETURN NEW;
END;
$function$", "-- 2. FUNCIÓN PARA LIMPIAR DATOS HISTÓRICOS
-- Eliminar costos duplicados de "Consumo de Inventario"
CREATE OR REPLACE FUNCTION public.cleanup_duplicate_inventory_costs()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  duplicate_costs_count INTEGER := 0;
  cleaned_costs_count INTEGER := 0;
  cost_record RECORD;
  maintenance_category_id UUID;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar la limpieza de duplicados';
  END IF;

  -- Obtener ID de categoría de mantenimiento
  SELECT id INTO maintenance_category_id
  FROM public.cost_categories
  WHERE name ILIKE '%mantenimiento%' 
  LIMIT 1;

  -- Contar costos de "Consumo de Inventario" con valores sospechosos
  SELECT COUNT(*) INTO duplicate_costs_count
  FROM public.costs c
  WHERE c.category_id = maintenance_category_id
    AND c.subcategory = 'Consumo de Inventario'
    AND (c.amount = 0.01 OR c.description ILIKE '%consumo de inventario%');

  RAISE NOTICE 'Encontrados % costos duplicados de consumo de inventario', duplicate_costs_count;

  -- Eliminar costos duplicados y actualizar crane_parts asociados
  FOR cost_record IN 
    SELECT c.*, cp.id as crane_part_id
    FROM public.costs c
    LEFT JOIN public.crane_parts cp ON c.id = cp.cost_id
    WHERE c.category_id = maintenance_category_id
      AND c.subcategory = 'Consumo de Inventario'
      AND (c.amount = 0.01 OR c.description ILIKE '%consumo de inventario%')
  LOOP
    -- Desvincular crane_parts del cost que se va a eliminar
    IF cost_record.crane_part_id IS NOT NULL THEN
      UPDATE public.crane_parts 
      SET cost_id = NULL,
          notes = COALESCE(notes, '') || ' [Cost duplicado eliminado automáticamente]'
      WHERE id = cost_record.crane_part_id;
    END IF;

    -- Eliminar el cost duplicado
    DELETE FROM public.costs WHERE id = cost_record.id;
    cleaned_costs_count := cleaned_costs_count + 1;

    RAISE NOTICE 'Eliminado cost duplicado: % ($%)', cost_record.description, cost_record.amount;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_duplicates_found', duplicate_costs_count,
    'costs_cleaned', cleaned_costs_count,
    'message', format('Limpieza completada: eliminados %s costos duplicados de consumo de inventario', cleaned_costs_count)
  );
END;
$function$", "-- 3. FUNCIÓN PARA RECALCULAR COSTOS EN CRANE_PARTS EXISTENTES
CREATE OR REPLACE FUNCTION public.recalculate_crane_parts_costs()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  updated_parts_count INTEGER := 0;
  part_record RECORD;
  item_unit_cost NUMERIC;
  fallback_unit_cost NUMERIC;
  final_unit_cost NUMERIC;
  item_name TEXT;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden recalcular costos de crane_parts';
  END IF;

  -- Recalcular costos para crane_parts con inventory_movement_id
  FOR part_record IN 
    SELECT cp.*, im.item_id
    FROM public.crane_parts cp
    JOIN public.inventory_movements im ON cp.inventory_movement_id = im.id
    WHERE cp.unit_price <= 0.01  -- Solo los que tienen costos incorrectos
      AND im.movement_type = 'exit'
  LOOP
    -- Obtener costo real del item
    SELECT unit_cost, name INTO item_unit_cost, item_name
    FROM public.inventory_items 
    WHERE id = part_record.item_id;

    -- Determinar el costo a usar
    IF item_unit_cost IS NOT NULL AND item_unit_cost > 0 THEN
      final_unit_cost := item_unit_cost;
    ELSE
      -- Fallback: promedio histórico
      SELECT AVG(unit_cost) INTO fallback_unit_cost
      FROM public.inventory_movements 
      WHERE item_id = part_record.item_id 
        AND movement_type IN ('entry', 'purchase')
        AND unit_cost > 0;

      final_unit_cost := COALESCE(fallback_unit_cost, part_record.unit_price);
    END IF;

    -- Actualizar crane_parts con el costo correcto
    UPDATE public.crane_parts
    SET 
      unit_price = final_unit_cost,
      total_value = final_unit_cost * ABS(quantity),
      notes = COALESCE(notes, '') || format(' [Costo recalculado: $%s -> $%s]', part_record.unit_price, final_unit_cost),
      updated_at = NOW()
    WHERE id = part_record.id;

    updated_parts_count := updated_parts_count + 1;

    RAISE NOTICE 'Actualizado crane_part %: % de $% a $%', 
      part_record.id, part_record.part_name, part_record.unit_price, final_unit_cost;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'updated_parts', updated_parts_count,
    'message', format('Recalculados costos de %s registros en crane_parts', updated_parts_count)
  );
END;
$function$", "-- 4. FUNCIÓN PARA EJECUTAR LIMPIEZA COMPLETA
CREATE OR REPLACE FUNCTION public.fix_inventory_cost_issues()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  cleanup_result jsonb;
  recalc_result jsonb;
  final_result jsonb;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar la corrección completa';
  END IF;

  RAISE NOTICE 'Iniciando corrección completa de problemas de inventario...';

  -- Paso 1: Limpiar costos duplicados
  SELECT public.cleanup_duplicate_inventory_costs() INTO cleanup_result;

  -- Paso 2: Recalcular costos en crane_parts
  SELECT public.recalculate_crane_parts_costs() INTO recalc_result;

  -- Compilar resultado final
  final_result := jsonb_build_object(
    'success', true,
    'timestamp', NOW(),
    'cleanup_phase', cleanup_result,
    'recalculation_phase', recalc_result,
    'message', 'Corrección completa de problemas de inventario ejecutada exitosamente'
  );

  RAISE NOTICE 'Corrección completa finalizada exitosamente';
  RETURN final_result;
END;
$function$"]

["-- Crear función para corregir el costo unitario del producto "Materiales Eléctricos"
CREATE OR REPLACE FUNCTION public.fix_materiales_electricos_unit_cost()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  item_id_found UUID;
  avg_historical_cost NUMERIC;
  updated_count INTEGER := 0;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden corregir costos de catálogo';
  END IF;

  -- Buscar el item "Materiales Eléctricos"
  SELECT id INTO item_id_found
  FROM public.inventory_items
  WHERE LOWER(name) LIKE '%materiales%electricos%' 
     OR LOWER(name) LIKE '%materiales%eléctricos%'
  LIMIT 1;

  IF item_id_found IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No se encontró el producto "Materiales Eléctricos"'
    );
  END IF;

  -- Calcular costo promedio de las entradas históricas
  SELECT AVG(unit_cost) INTO avg_historical_cost
  FROM public.inventory_movements 
  WHERE item_id = item_id_found 
    AND movement_type IN ('entry', 'purchase')
    AND unit_cost > 0
    AND unit_cost IS NOT NULL;

  -- Si no hay costo histórico, usar el valor conocido de $19,620
  IF avg_historical_cost IS NULL OR avg_historical_cost = 0 THEN
    avg_historical_cost := 19620.00;
  END IF;

  -- Actualizar el unit_cost en inventory_items
  UPDATE public.inventory_items
  SET 
    unit_cost = avg_historical_cost,
    updated_at = NOW()
  WHERE id = item_id_found
    AND (unit_cost IS NULL OR unit_cost = 0);

  GET DIAGNOSTICS updated_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'item_id', item_id_found,
    'updated_count', updated_count,
    'new_unit_cost', avg_historical_cost,
    'message', format('Costo unitario actualizado a $%s', avg_historical_cost)
  );
END;
$function$"]

["-- Create selective payment application function
CREATE OR REPLACE FUNCTION public.apply_payment_selective(
  p_payment_id UUID,
  p_fiscal_numbers TEXT[] DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  remaining_amount DECIMAL;
  applied_count INTEGER := 0;
  total_applied DECIMAL := 0;
  application_results JSONB := '[]'::jsonb;
  current_user_id UUID;
BEGIN
  -- Get current user
  current_user_id := auth.uid();
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Usuario no autenticado';
  END IF;

  -- Get payment details
  SELECT * INTO payment_record
  FROM public.payments 
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Pago no encontrado'
    );
  END IF;

  remaining_amount := payment_record.amount - COALESCE(payment_record.applied_amount, 0);

  IF remaining_amount <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El pago ya está completamente aplicado'
    );
  END IF;

  -- If fiscal numbers provided, apply to specific invoices
  IF p_fiscal_numbers IS NOT NULL AND array_length(p_fiscal_numbers, 1) > 0 THEN
    FOR invoice_record IN 
      SELECT i.id, i.folio, i.numero_fiscal, i.total, COALESCE(i.paid_amount, 0) as paid_amount
      FROM public.invoices i
      WHERE i.client_id = payment_record.client_id
        AND i.numero_fiscal = ANY(p_fiscal_numbers)
        AND i.status IN ('sent', 'overdue', 'partial')
        AND (i.total - COALESCE(i.paid_amount, 0)) > 0
      ORDER BY i.issue_date ASC
    LOOP
      DECLARE
        pending_amount DECIMAL;
        application_amount DECIMAL;
      BEGIN
        pending_amount := invoice_record.total - invoice_record.paid_amount;
        application_amount := LEAST(pending_amount, remaining_amount);

        IF application_amount > 0 THEN
          -- Insert payment application
          INSERT INTO public.payment_applications (
            payment_id,
            invoice_id,
            applied_amount,
            application_method,
            created_by
          ) VALUES (
            p_payment_id,
            invoice_record.id,
            application_amount,
            'selective'::application_method,
            current_user_id
          );

          remaining_amount := remaining_amount - application_amount;
          total_applied := total_applied + application_amount;
          applied_count := applied_count + 1;

          -- Add to results
          application_results := application_results || jsonb_build_object(
            'invoice_id', invoice_record.id,
            'folio', invoice_record.folio,
            'fiscal_number', invoice_record.numero_fiscal,
            'applied_amount', application_amount
          );

          -- If payment is fully applied, stop
          IF remaining_amount <= 0.01 THEN
            EXIT;
          END IF;
        END IF;
      END;
    END LOOP;
  ELSE
    -- Apply FIFO if no specific invoices provided
    FOR invoice_record IN 
      SELECT i.id, i.folio, i.numero_fiscal, i.total, COALESCE(i.paid_amount, 0) as paid_amount
      FROM public.invoices i
      WHERE i.client_id = payment_record.client_id
        AND i.status IN ('sent', 'overdue', 'partial')
        AND (i.total - COALESCE(i.paid_amount, 0)) > 0
      ORDER BY i.issue_date ASC
    LOOP
      DECLARE
        pending_amount DECIMAL;
        application_amount DECIMAL;
      BEGIN
        pending_amount := invoice_record.total - invoice_record.paid_amount;
        application_amount := LEAST(pending_amount, remaining_amount);

        IF application_amount > 0 THEN
          -- Insert payment application
          INSERT INTO public.payment_applications (
            payment_id,
            invoice_id,
            applied_amount,
            application_method,
            created_by
          ) VALUES (
            p_payment_id,
            invoice_record.id,
            application_amount,
            'fifo'::application_method,
            current_user_id
          );

          remaining_amount := remaining_amount - application_amount;
          total_applied := total_applied + application_amount;
          applied_count := applied_count + 1;

          -- Add to results
          application_results := application_results || jsonb_build_object(
            'invoice_id', invoice_record.id,
            'folio', invoice_record.folio,
            'fiscal_number', invoice_record.numero_fiscal,
            'applied_amount', application_amount
          );

          -- If payment is fully applied, stop
          IF remaining_amount <= 0.01 THEN
            EXIT;
          END IF;
        END IF;
      END;
    END LOOP;
  END IF;

  -- Update payment status
  UPDATE public.payments
  SET 
    applied_amount = COALESCE(applied_amount, 0) + total_applied,
    status = CASE 
      WHEN (COALESCE(applied_amount, 0) + total_applied) >= amount THEN 'applied'::payment_status
      WHEN total_applied > 0 THEN 'partial'::payment_status
      ELSE status
    END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'applied_invoices', applied_count,
    'total_applied', total_applied,
    'remaining_amount', remaining_amount,
    'applications', application_results,
    'message', format('Pago aplicado exitosamente a %s facturas por un total de $%s', applied_count, total_applied)
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Error aplicando pago: ' || SQLERRM,
      'error_code', SQLSTATE
    );
END;
$function$"]

["-- Update apply_payment_selective function to add apply_only_to_specified parameter
CREATE OR REPLACE FUNCTION public.apply_payment_selective(
  p_payment_id UUID,
  p_fiscal_numbers TEXT[],
  p_apply_only_to_specified BOOLEAN DEFAULT FALSE
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $function$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
  v_amount_to_apply DECIMAL;
  v_remaining_payment DECIMAL;
  v_applied_total DECIMAL := 0;
  v_applications_created INTEGER := 0;
  v_error_msg TEXT;
BEGIN
  -- Get payment information
  SELECT * INTO v_payment
  FROM payments 
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Pago no encontrado'
    );
  END IF;

  -- Initialize remaining payment amount
  v_remaining_payment := v_payment.amount - COALESCE(v_payment.applied_amount, 0);

  IF v_remaining_payment <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El pago ya está completamente aplicado'
    );
  END IF;

  -- First phase: Apply to specified invoices by fiscal number
  IF array_length(p_fiscal_numbers, 1) > 0 THEN
    FOR i IN 1..array_length(p_fiscal_numbers, 1) LOOP
      EXIT WHEN v_remaining_payment <= 0;

      -- Find invoice by fiscal number for this client
      SELECT * INTO v_invoice
      FROM invoices 
      WHERE numero_fiscal = p_fiscal_numbers[i]
        AND client_id = v_payment.client_id
        AND status IN ('sent', 'overdue', 'partial')
        AND (total - COALESCE(paid_amount, 0)) > 0;

      IF FOUND THEN
        -- Calculate amount to apply (minimum of remaining payment and remaining invoice)
        v_amount_to_apply := LEAST(
          v_remaining_payment,
          v_invoice.total - COALESCE(v_invoice.paid_amount, 0)
        );

        -- Create payment application
        INSERT INTO payment_applications (
          payment_id,
          invoice_id,
          applied_amount,
          application_method,
          created_by
        ) VALUES (
          p_payment_id,
          v_invoice.id,
          v_amount_to_apply,
          'manual',
          v_payment.created_by
        );

        v_applied_total := v_applied_total + v_amount_to_apply;
        v_remaining_payment := v_remaining_payment - v_amount_to_apply;
        v_applications_created := v_applications_created + 1;

        RAISE NOTICE 'Applied % to invoice % (%)', v_amount_to_apply, v_invoice.folio, v_invoice.numero_fiscal;
      ELSE
        RAISE NOTICE 'Invoice with fiscal number % not found or not applicable', p_fiscal_numbers[i];
      END IF;
    END LOOP;
  END IF;

  -- Second phase: Apply remaining amount using FIFO (only if apply_only_to_specified is FALSE)
  IF NOT p_apply_only_to_specified AND v_remaining_payment > 0 THEN
    FOR v_invoice IN 
      SELECT *
      FROM invoices
      WHERE client_id = v_payment.client_id
        AND status IN ('sent', 'overdue', 'partial')
        AND (total - COALESCE(paid_amount, 0)) > 0
        AND id NOT IN (
          SELECT invoice_id 
          FROM payment_applications 
          WHERE payment_id = p_payment_id
        )
      ORDER BY issue_date ASC
    LOOP
      EXIT WHEN v_remaining_payment <= 0;

      v_amount_to_apply := LEAST(
        v_remaining_payment,
        v_invoice.total - COALESCE(v_invoice.paid_amount, 0)
      );

      INSERT INTO payment_applications (
        payment_id,
        invoice_id,
        applied_amount,
        application_method,
        created_by
      ) VALUES (
        p_payment_id,
        v_invoice.id,
        v_amount_to_apply,
        'fifo',
        v_payment.created_by
      );

      v_applied_total := v_applied_total + v_amount_to_apply;
      v_remaining_payment := v_remaining_payment - v_amount_to_apply;
      v_applications_created := v_applications_created + 1;

      RAISE NOTICE 'Applied % to invoice % via FIFO', v_amount_to_apply, v_invoice.folio;
    END LOOP;
  END IF;

  -- Update payment status
  UPDATE payments 
  SET 
    applied_amount = COALESCE(applied_amount, 0) + v_applied_total,
    status = CASE 
      WHEN (COALESCE(applied_amount, 0) + v_applied_total) >= amount THEN 'applied'::payment_status
      WHEN (COALESCE(applied_amount, 0) + v_applied_total) > 0 THEN 'partial'::payment_status
      ELSE 'pending'::payment_status
    END,
    updated_at = NOW()
  WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'applied_amount', v_applied_total,
    'remaining_amount', v_remaining_payment,
    'applications_created', v_applications_created,
    'apply_only_to_specified', p_apply_only_to_specified,
    'message', format('Aplicado %s en %s aplicaciones. Saldo restante: %s', 
      v_applied_total, v_applications_created, v_remaining_payment)
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', SQLERRM,
      'error_code', SQLSTATE
    );
END;
$function$"]

["-- Updated function to handle existing applications correctly
CREATE OR REPLACE FUNCTION public.fix_amphos_payment_applications()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $function$
DECLARE
  v_payment_id UUID := '9234da35-7e10-43e6-b918-b08d18b101be';
  v_removed_count INTEGER := 0;
  v_added_count INTEGER := 0;
  v_updated_count INTEGER := 0;
  v_final_applied DECIMAL;

  -- Invoices that should NOT be paid (to remove)
  wrong_applications UUID[] := ARRAY[
    '21a5dcbe-e8a8-4677-b395-f430c5f4cdf7', -- FACT-4004
    '5ce20c33-f779-4acf-a268-8e2f209149a0', -- FACT-4031  
    '44f1c6e9-c80e-4e0b-86b4-6464755c8cc1', -- FACT-4032
    'b45ab027-a221-4a4a-bde8-d5616864b853'  -- FACT-4035
  ];

  -- Invoices that should be paid
  v_fact_4011_id UUID := 'db1e10bc-5100-4691-af9b-a270e6f219c8';
  v_fact_4013_id UUID := '73a50b63-a8ec-48e2-b16c-505882afa3f7';
  v_existing_4013_app_id UUID;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar esta corrección';
  END IF;

  -- Step 1: Remove incorrect applications
  DELETE FROM payment_applications 
  WHERE id = ANY(wrong_applications);

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  -- Step 2: Check if FACT-4011 application exists, if not create it
  IF NOT EXISTS (
    SELECT 1 FROM payment_applications 
    WHERE payment_id = v_payment_id AND invoice_id = v_fact_4011_id
  ) THEN
    INSERT INTO payment_applications (
      payment_id,
      invoice_id, 
      applied_amount,
      application_method,
      created_by
    ) VALUES (
      v_payment_id,
      v_fact_4011_id,
      258388.00,
      'manual',
      auth.uid()
    );
    v_added_count := v_added_count + 1;
  END IF;

  -- Step 3: Update existing FACT-4013 application to complete payment
  SELECT id INTO v_existing_4013_app_id
  FROM payment_applications
  WHERE payment_id = v_payment_id AND invoice_id = v_fact_4013_id;

  IF v_existing_4013_app_id IS NOT NULL THEN
    UPDATE payment_applications
    SET applied_amount = 595000.00,  -- Complete total payment
        application_method = 'manual',
        updated_at = NOW()
    WHERE id = v_existing_4013_app_id;
    v_updated_count := 1;
  ELSE
    -- If for some reason it doesn't exist, create it
    INSERT INTO payment_applications (
      payment_id,
      invoice_id,
      applied_amount, 
      application_method,
      created_by
    ) VALUES (
      v_payment_id,
      v_fact_4013_id,
      595000.00,
      'manual',
      auth.uid()
    );
    v_added_count := v_added_count + 1;
  END IF;

  -- Step 4: Calculate final applied amount
  SELECT COALESCE(SUM(applied_amount), 0) INTO v_final_applied
  FROM payment_applications
  WHERE payment_id = v_payment_id;

  -- Step 5: Update payment status
  UPDATE payments 
  SET 
    applied_amount = v_final_applied,
    status = 'applied'::payment_status,
    updated_at = NOW()
  WHERE id = v_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'removed_applications', v_removed_count,
    'added_applications', v_added_count,
    'updated_applications', v_updated_count,
    'final_applied_amount', v_final_applied,
    'message', format('Corregido pago Amphos 21: eliminadas %s aplicaciones incorrectas, agregadas %s, actualizadas %s. Total aplicado: $%s', 
      v_removed_count, v_added_count, v_updated_count, v_final_applied)
  );
END;
$function$"]

["-- Final corrected function without updated_at column
CREATE OR REPLACE FUNCTION public.fix_amphos_payment_applications()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $function$
DECLARE
  v_payment_id UUID := '9234da35-7e10-43e6-b918-b08d18b101be';
  v_removed_count INTEGER := 0;
  v_added_count INTEGER := 0;
  v_updated_count INTEGER := 0;
  v_final_applied DECIMAL;

  -- Invoices that should NOT be paid (to remove)
  wrong_applications UUID[] := ARRAY[
    '21a5dcbe-e8a8-4677-b395-f430c5f4cdf7', -- FACT-4004
    '5ce20c33-f779-4acf-a268-8e2f209149a0', -- FACT-4031  
    '44f1c6e9-c80e-4e0b-86b4-6464755c8cc1', -- FACT-4032
    'b45ab027-a221-4a4a-bde8-d5616864b853'  -- FACT-4035
  ];

  -- Invoices that should be paid
  v_fact_4011_id UUID := 'db1e10bc-5100-4691-af9b-a270e6f219c8';
  v_fact_4013_id UUID := '73a50b63-a8ec-48e2-b16c-505882afa3f7';
  v_existing_4013_app_id UUID;
BEGIN
  -- Verificar permisos de administrador
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) != 'admin' THEN
    RAISE EXCEPTION 'Solo los administradores pueden ejecutar esta corrección';
  END IF;

  -- Step 1: Remove incorrect applications
  DELETE FROM payment_applications 
  WHERE id = ANY(wrong_applications);

  GET DIAGNOSTICS v_removed_count = ROW_COUNT;

  -- Step 2: Check if FACT-4011 application exists, if not create it
  IF NOT EXISTS (
    SELECT 1 FROM payment_applications 
    WHERE payment_id = v_payment_id AND invoice_id = v_fact_4011_id
  ) THEN
    INSERT INTO payment_applications (
      payment_id,
      invoice_id, 
      applied_amount,
      application_method,
      created_by
    ) VALUES (
      v_payment_id,
      v_fact_4011_id,
      258388.00,
      'manual',
      auth.uid()
    );
    v_added_count := v_added_count + 1;
  END IF;

  -- Step 3: Update existing FACT-4013 application to complete payment
  SELECT id INTO v_existing_4013_app_id
  FROM payment_applications
  WHERE payment_id = v_payment_id AND invoice_id = v_fact_4013_id;

  IF v_existing_4013_app_id IS NOT NULL THEN
    UPDATE payment_applications
    SET applied_amount = 595000.00,  -- Complete total payment
        application_method = 'manual'
    WHERE id = v_existing_4013_app_id;
    v_updated_count := 1;
  ELSE
    -- If for some reason it doesn't exist, create it
    INSERT INTO payment_applications (
      payment_id,
      invoice_id,
      applied_amount, 
      application_method,
      created_by
    ) VALUES (
      v_payment_id,
      v_fact_4013_id,
      595000.00,
      'manual',
      auth.uid()
    );
    v_added_count := v_added_count + 1;
  END IF;

  -- Step 4: Calculate final applied amount
  SELECT COALESCE(SUM(applied_amount), 0) INTO v_final_applied
  FROM payment_applications
  WHERE payment_id = v_payment_id;

  -- Step 5: Update payment status
  UPDATE payments 
  SET 
    applied_amount = v_final_applied,
    status = 'applied'::payment_status,
    updated_at = NOW()
  WHERE id = v_payment_id;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'removed_applications', v_removed_count,
    'added_applications', v_added_count,
    'updated_applications', v_updated_count,
    'final_applied_amount', v_final_applied,
    'message', format('Corregido pago Amphos 21: eliminadas %s aplicaciones incorrectas, agregadas %s, actualizadas %s. Total aplicado: $%s', 
      v_removed_count, v_added_count, v_updated_count, v_final_applied)
  );
END;
$function$"]

["-- Corregir funciones de aplicación de pagos para evitar duplicación
-- Primero hacemos DROP y luego recreamos las funciones

-- 1. Drop de funciones existentes
DROP FUNCTION IF EXISTS public.apply_payment_fifo(uuid, uuid)", "DROP FUNCTION IF EXISTS public.apply_payment_manual(uuid, jsonb)", "-- 2. Recrear apply_payment_fifo sin actualización manual de payments
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(p_payment_id uuid, p_client_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  amount_to_apply DECIMAL;
  remaining_payment DECIMAL;
  total_applied DECIMAL := 0;
  applications_count INTEGER := 0;
BEGIN
  -- Verificar permisos
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tienes permisos para aplicar pagos';
  END IF;

  -- Obtener datos del pago
  SELECT * INTO payment_record
  FROM public.payments 
  WHERE id = p_payment_id AND client_id = p_client_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pago no encontrado';
  END IF;

  remaining_payment := payment_record.amount - COALESCE(payment_record.applied_amount, 0);

  IF remaining_payment <= 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'El pago ya está completamente aplicado',
      'applications_created', 0
    );
  END IF;

  -- Aplicar pago a facturas pendientes usando FIFO
  FOR invoice_record IN 
    SELECT 
      i.id,
      i.folio,
      i.total,
      COALESCE(i.paid_amount, 0) as paid_amount,
      (i.total - COALESCE(i.paid_amount, 0)) as remaining_amount
    FROM public.invoices i
    WHERE i.client_id = p_client_id
      AND i.status IN ('sent', 'overdue', 'partial')
      AND (i.total - COALESCE(i.paid_amount, 0)) > 0
    ORDER BY i.issue_date ASC, i.created_at ASC
  LOOP
    EXIT WHEN remaining_payment <= 0;

    -- Calcular monto a aplicar
    amount_to_apply := LEAST(remaining_payment, invoice_record.remaining_amount);

    -- Insertar aplicación de pago (el trigger actualizará payments automáticamente)
    INSERT INTO public.payment_applications (
      payment_id,
      invoice_id,
      applied_amount,
      application_method,
      created_by
    ) VALUES (
      p_payment_id,
      invoice_record.id,
      amount_to_apply,
      'fifo',
      auth.uid()
    );

    remaining_payment := remaining_payment - amount_to_apply;
    total_applied := total_applied + amount_to_apply;
    applications_count := applications_count + 1;

    RAISE NOTICE 'Aplicados $% a factura % (Folio: %)', 
      amount_to_apply, invoice_record.id, invoice_record.folio;
  END LOOP;

  -- NO actualizamos payments manualmente - el trigger lo hace automáticamente

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'total_applied', total_applied,
    'applications_created', applications_count,
    'message', format('Aplicados $%s en %s facturas usando FIFO', total_applied, applications_count)
  );
END;
$function$", "-- 3. Recrear apply_payment_manual sin actualizaciones manuales
CREATE OR REPLACE FUNCTION public.apply_payment_manual(
  p_payment_id uuid,
  p_applications jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  payment_record RECORD;
  application JSONB;
  invoice_id_to_apply UUID;
  amount_to_apply DECIMAL;
  total_applied DECIMAL := 0;
  applications_count INTEGER := 0;
  available_amount DECIMAL;
BEGIN
  -- Verificar permisos
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tienes permisos para aplicar pagos manualmente';
  END IF;

  -- Obtener información del pago
  SELECT * INTO payment_record
  FROM public.payments 
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pago no encontrado';
  END IF;

  available_amount := payment_record.amount - COALESCE(payment_record.applied_amount, 0);

  -- Procesar cada aplicación manual
  FOR application IN SELECT * FROM jsonb_array_elements(p_applications)
  LOOP
    invoice_id_to_apply := (application->>'invoice_id')::UUID;
    amount_to_apply := (application->>'amount')::DECIMAL;

    -- Validar que hay monto disponible
    IF total_applied + amount_to_apply > available_amount THEN
      RAISE EXCEPTION 'Monto total a aplicar ($%) excede el disponible ($%)', 
        total_applied + amount_to_apply, available_amount;
    END IF;

    -- Validar que la factura existe y pertenece al mismo cliente
    IF NOT EXISTS (
      SELECT 1 FROM public.invoices 
      WHERE id = invoice_id_to_apply 
        AND client_id = payment_record.client_id
    ) THEN
      RAISE EXCEPTION 'Factura no válida o no pertenece al mismo cliente';
    END IF;

    -- Insertar aplicación (el trigger actualizará automáticamente payments e invoices)
    INSERT INTO public.payment_applications (
      payment_id,
      invoice_id,
      applied_amount,
      application_method,
      created_by
    ) VALUES (
      p_payment_id,
      invoice_id_to_apply,
      amount_to_apply,
      'manual',
      auth.uid()
    );

    total_applied := total_applied + amount_to_apply;
    applications_count := applications_count + 1;
  END LOOP;

  -- NO actualizamos payments ni invoices manualmente - los triggers lo hacen automáticamente

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'total_applied', total_applied,
    'applications_created', applications_count,
    'message', format('Aplicación manual exitosa: $%s en %s facturas', total_applied, applications_count)
  );
END;
$function$", "-- 4. Ejecutar limpieza de datos existentes
SELECT fix_applied_amount_duplications()"]

["-- ================================================================
-- CORRECCIÓN DE SOBREPAGOS Y VALIDACIÓN ESTRICTA
-- Elimina aplicaciones de pago que exceden el total de facturas
-- y agrega validación para prevenir sobrepagos futuros
-- ================================================================

-- PASO 1: Corregir FACT-4004 eliminando aplicación excedente
DO $$
DECLARE
  v_invoice_id UUID;
  v_invoice_total NUMERIC;
  v_application_to_remove UUID;
BEGIN
  -- Obtener ID de FACT-4004
  SELECT id, total INTO v_invoice_id, v_invoice_total
  FROM invoices 
  WHERE folio = 'FACT-4004';

  IF v_invoice_id IS NOT NULL THEN
    -- Eliminar la aplicación parcial de $258.388 (la primera)
    -- Mantener solo la aplicación completa de $297.500
    DELETE FROM payment_applications
    WHERE id IN (
      SELECT pa.id
      FROM payment_applications pa
      WHERE pa.invoice_id = v_invoice_id
        AND pa.applied_amount < v_invoice_total
      ORDER BY pa.created_at
      LIMIT 1
    )
    RETURNING id INTO v_application_to_remove;

    IF v_application_to_remove IS NOT NULL THEN
      RAISE NOTICE 'Eliminada aplicación excedente % de FACT-4004', v_application_to_remove;
    END IF;

    -- El trigger auto_update_invoice_status recalculará automáticamente
    -- paid_amount y remaining_amount

    -- Forzar actualización manual para asegurar
    UPDATE invoices
    SET updated_at = NOW()
    WHERE id = v_invoice_id;
  END IF;
END $$", "-- PASO 2: Función helper para validar sobrepagos
CREATE OR REPLACE FUNCTION public.validate_payment_application_amount(
  p_invoice_id UUID,
  p_new_amount NUMERIC,
  p_excluding_application_id UUID DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice_total NUMERIC;
  v_current_paid NUMERIC;
  v_available_amount NUMERIC;
BEGIN
  -- Obtener total de la factura
  SELECT total INTO v_invoice_total
  FROM invoices
  WHERE id = p_invoice_id;

  IF v_invoice_total IS NULL THEN
    RAISE EXCEPTION 'Factura no encontrada';
  END IF;

  -- Calcular monto ya pagado (excluyendo aplicación específica si se indica)
  SELECT COALESCE(SUM(applied_amount), 0) INTO v_current_paid
  FROM payment_applications
  WHERE invoice_id = p_invoice_id
    AND (p_excluding_application_id IS NULL OR id != p_excluding_application_id);

  -- Calcular monto disponible
  v_available_amount := v_invoice_total - v_current_paid;

  -- Validar que el nuevo monto no exceda lo disponible
  IF p_new_amount > v_available_amount THEN
    RAISE EXCEPTION 'Monto de aplicación ($%) excede el monto disponible ($%) de la factura', 
      p_new_amount, v_available_amount
    USING HINT = format('Total factura: $%, Ya pagado: $%, Disponible: $%', 
      v_invoice_total, v_current_paid, v_available_amount);
  END IF;

  RETURN TRUE;
END;
$function$", "-- PASO 3: Agregar trigger de validación en payment_applications
CREATE OR REPLACE FUNCTION public.prevent_overpayment_on_application()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Validar en INSERT
  IF TG_OP = 'INSERT' THEN
    PERFORM validate_payment_application_amount(NEW.invoice_id, NEW.applied_amount);
  END IF;

  -- Validar en UPDATE si cambia el monto o la factura
  IF TG_OP = 'UPDATE' AND (
    NEW.applied_amount != OLD.applied_amount OR 
    NEW.invoice_id != OLD.invoice_id
  ) THEN
    PERFORM validate_payment_application_amount(
      NEW.invoice_id, 
      NEW.applied_amount,
      OLD.id  -- Excluir el monto anterior de esta aplicación
    );
  END IF;

  RETURN NEW;
END;
$function$", "-- Crear trigger
DROP TRIGGER IF EXISTS prevent_overpayment_trigger ON payment_applications", "CREATE TRIGGER prevent_overpayment_trigger
  BEFORE INSERT OR UPDATE ON payment_applications
  FOR EACH ROW
  EXECUTE FUNCTION prevent_overpayment_on_application()", "-- PASO 4: Mejorar apply_payment_fifo con validación preventiva
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(p_payment_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
  v_remaining NUMERIC;
  v_to_apply NUMERIC;
  applications_count INTEGER := 0;
BEGIN
  -- Obtener información del pago
  SELECT * INTO v_payment
  FROM payments
  WHERE id = p_payment_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Pago no encontrado'
    );
  END IF;

  v_remaining := v_payment.amount - COALESCE(v_payment.applied_amount, 0);

  IF v_remaining <= 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'El pago ya está completamente aplicado'
    );
  END IF;

  -- Aplicar a facturas pendientes del mismo cliente (FIFO: más antiguas primero)
  FOR v_invoice IN 
    SELECT 
      i.id,
      i.folio,
      i.total,
      i.paid_amount,
      (i.total - COALESCE(i.paid_amount, 0)) as remaining_amount
    FROM invoices i
    WHERE i.client_id = v_payment.client_id
      AND i.status IN ('sent', 'overdue', 'partial')
      AND (i.total - COALESCE(i.paid_amount, 0)) > 0
    ORDER BY i.issue_date ASC, i.created_at ASC
  LOOP
    EXIT WHEN v_remaining <= 0;

    -- Calcular cuánto aplicar (el menor entre lo que queda del pago y lo que falta de la factura)
    v_to_apply := LEAST(v_remaining, v_invoice.remaining_amount);

    -- VALIDACIÓN PREVENTIVA: Verificar que no cause sobrepago
    BEGIN
      PERFORM validate_payment_application_amount(v_invoice.id, v_to_apply);

      -- Aplicar el pago
      INSERT INTO payment_applications (
        payment_id,
        invoice_id,
        applied_amount,
        application_method,
        notes,
        created_by
      ) VALUES (
        p_payment_id,
        v_invoice.id,
        v_to_apply,
        'fifo',
        format('Aplicación automática FIFO: $%s a %s', v_to_apply, v_invoice.folio),
        auth.uid()
      );

      v_remaining := v_remaining - v_to_apply;
      applications_count := applications_count + 1;

      RAISE NOTICE 'Aplicados $% a factura %', v_to_apply, v_invoice.folio;

    EXCEPTION
      WHEN OTHERS THEN
        -- Si falla la validación, registrar y continuar con la siguiente factura
        RAISE WARNING 'No se pudo aplicar a factura %: %', v_invoice.folio, SQLERRM;
        CONTINUE;
    END;
  END LOOP;

  -- El trigger auto_update_invoice_status actualizará automáticamente
  -- los montos de las facturas afectadas

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', p_payment_id,
    'applications_count', applications_count,
    'remaining_amount', v_remaining,
    'message', format('Aplicadas %s facturas, monto restante: $%s', applications_count, v_remaining)
  );
END;
$function$", "-- PASO 5: Verificar integridad final
DO $$
DECLARE
  v_overpayments INTEGER;
  v_overpayment_details JSONB;
BEGIN
  -- Buscar facturas con sobrepago
  SELECT 
    COUNT(*),
    jsonb_agg(
      jsonb_build_object(
        'folio', folio,
        'total', total,
        'paid_amount', paid_amount,
        'overpaid_by', paid_amount - total
      )
    )
  INTO v_overpayments, v_overpayment_details
  FROM invoices
  WHERE paid_amount > total;

  IF v_overpayments > 0 THEN
    RAISE WARNING 'Se encontraron % facturas con sobrepago después de la corrección: %', 
      v_overpayments, v_overpayment_details;
  ELSE
    RAISE NOTICE 'Sistema de pagos completamente sincronizado. Sin sobrepagos detectados.';
  END IF;
END $$"]

["-- FASE 1: Trigger de sincronización automática
CREATE OR REPLACE FUNCTION public.sync_inventory_cost_to_movement()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_category_name TEXT;
  v_inventory_item_id UUID;
  v_location_id UUID;
  v_category_id UUID;
  v_quantity INT := 1;
  v_unit_cost NUMERIC;
  v_movement_id UUID;
BEGIN
  SELECT name INTO v_category_name FROM cost_categories WHERE id = NEW.category_id;
  IF v_category_name NOT ILIKE '%inventario%' THEN RETURN NEW; END IF;
  IF NEW.inventory_movement_id IS NOT NULL THEN RETURN NEW; END IF;

  IF NEW.purchase_quantity IS NOT NULL AND NEW.purchase_quantity > 0 THEN
    v_quantity := NEW.purchase_quantity;
  END IF;

  IF NEW.purchase_unit_cost IS NOT NULL AND NEW.purchase_unit_cost > 0 THEN
    v_unit_cost := NEW.purchase_unit_cost;
  ELSE
    v_unit_cost := NEW.amount / v_quantity;
  END IF;

  SELECT id INTO v_category_id FROM inventory_categories WHERE name ILIKE '%compra%' OR name ILIKE '%general%' ORDER BY created_at ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    INSERT INTO inventory_categories (name, description, code) VALUES ('Compras Generales', 'Productos comprados para inventario', 'PURCHASES') RETURNING id INTO v_category_id;
  END IF;

  SELECT id INTO v_inventory_item_id FROM inventory_items WHERE LOWER(TRIM(name)) = LOWER(TRIM(NEW.description)) LIMIT 1;
  IF v_inventory_item_id IS NULL THEN
    INSERT INTO inventory_items (name, description, category_id, unit_of_measure, minimum_stock, unit_cost, is_active)
    VALUES (NEW.description, 'Creado desde costos', v_category_id, 'unidad', 1, v_unit_cost, true) RETURNING id INTO v_inventory_item_id;
  END IF;

  SELECT id INTO v_location_id FROM inventory_locations WHERE is_active = true ORDER BY created_at ASC LIMIT 1;
  IF v_location_id IS NULL THEN
    INSERT INTO inventory_locations (name, code, description, is_active) VALUES ('Bodega Principal', 'MAIN', 'Ubicación principal', true) RETURNING id INTO v_location_id;
  END IF;

  INSERT INTO inventory_movements (item_id, location_id, movement_type, quantity, unit_cost, total_cost, movement_date, reason, crane_id, cost_id, observations, created_by, status)
  VALUES (v_inventory_item_id, v_location_id, 'entry', v_quantity, v_unit_cost, NEW.amount, NEW.date, 'Compra desde Costos', NEW.crane_id, NEW.id, COALESCE(NEW.notes, 'Auto-sync'), NEW.created_by, 'active')
  RETURNING id INTO v_movement_id;

  UPDATE costs SET inventory_movement_id = v_movement_id WHERE id = NEW.id;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$$", "DROP TRIGGER IF EXISTS sync_inventory_cost_trigger ON costs", "CREATE TRIGGER sync_inventory_cost_trigger AFTER INSERT ON costs FOR EACH ROW EXECUTE FUNCTION sync_inventory_cost_to_movement()", "-- FASE 2: Agregar campos de compra
ALTER TABLE public.costs ADD COLUMN IF NOT EXISTS purchase_quantity INTEGER", "ALTER TABLE public.costs ADD COLUMN IF NOT EXISTS purchase_unit_cost NUMERIC(12, 2)"]

["-- FASE 6: Backfill de datos históricos de inventario
DO $$
DECLARE
  v_cost_record RECORD;
  v_inventory_item_id UUID;
  v_location_id UUID;
  v_category_id UUID;
  v_movement_id UUID;
  v_processed_count INT := 0;
  v_error_count INT := 0;
BEGIN
  SELECT id INTO v_location_id FROM inventory_locations WHERE is_active = true ORDER BY created_at ASC LIMIT 1;
  IF v_location_id IS NULL THEN
    INSERT INTO inventory_locations (name, code, description, is_active) VALUES ('Bodega Principal', 'MAIN', 'Ubicación principal', true) RETURNING id INTO v_location_id;
  END IF;

  SELECT id INTO v_category_id FROM inventory_categories WHERE name ILIKE '%compra%' OR name ILIKE '%general%' ORDER BY created_at ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    INSERT INTO inventory_categories (name, description, code) VALUES ('Compras Generales', 'Productos comprados', 'PURCHASES') RETURNING id INTO v_category_id;
  END IF;

  FOR v_cost_record IN
    SELECT c.id, c.description, c.amount, c.date, c.crane_id, c.created_by, c.notes,
           COALESCE(c.purchase_quantity, 1) as quantity,
           COALESCE(c.purchase_unit_cost, c.amount) as unit_cost
    FROM costs c
    JOIN cost_categories cc ON c.category_id = cc.id
    WHERE cc.name ILIKE '%inventario%' AND c.inventory_movement_id IS NULL
    ORDER BY c.date ASC
  LOOP
    BEGIN
      SELECT id INTO v_inventory_item_id FROM inventory_items WHERE LOWER(TRIM(name)) = LOWER(TRIM(v_cost_record.description)) LIMIT 1;
      IF v_inventory_item_id IS NULL THEN
        INSERT INTO inventory_items (name, description, category_id, unit_of_measure, minimum_stock, unit_cost, is_active)
        VALUES (v_cost_record.description, 'Migrado', v_category_id, 'unidad', 1, v_cost_record.unit_cost, true) RETURNING id INTO v_inventory_item_id;
      END IF;

      INSERT INTO inventory_movements (item_id, location_id, movement_type, quantity, unit_cost, total_cost, movement_date, reason, crane_id, cost_id, observations, created_by, status)
      VALUES (v_inventory_item_id, v_location_id, 'entry', v_cost_record.quantity, v_cost_record.unit_cost, v_cost_record.amount, v_cost_record.date, 'Migración', v_cost_record.crane_id, v_cost_record.id, COALESCE(v_cost_record.notes, 'Auto'), v_cost_record.created_by, 'active')
      RETURNING id INTO v_movement_id;

      UPDATE costs SET inventory_movement_id = v_movement_id WHERE id = v_cost_record.id;
      v_processed_count := v_processed_count + 1;
    EXCEPTION WHEN OTHERS THEN
      v_error_count := v_error_count + 1;
    END;
  END LOOP;
END $$"]

["-- Agregar campo immediate_consumption a la tabla costs
ALTER TABLE public.costs 
ADD COLUMN IF NOT EXISTS immediate_consumption BOOLEAN DEFAULT false", "COMMENT ON COLUMN public.costs.immediate_consumption IS 
'Indica si la compra debe consumirse inmediatamente. Si es true, se crea automáticamente un movimiento de salida a la grúa seleccionada.'", "-- Modificar el trigger para manejar consumo inmediato
CREATE OR REPLACE FUNCTION public.sync_inventory_cost_to_movement()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_category_name TEXT;
  v_inventory_item_id UUID;
  v_location_id UUID;
  v_category_id UUID;
  v_quantity INT := 1;
  v_unit_cost NUMERIC;
  v_movement_id UUID;
BEGIN
  SELECT cc.name INTO v_category_name FROM cost_categories cc WHERE cc.id = NEW.category_id;
  IF v_category_name IS NULL OR v_category_name NOT ILIKE '%inventario%' THEN RETURN NEW; END IF;

  SELECT id INTO v_location_id FROM inventory_locations WHERE is_active = true ORDER BY created_at ASC LIMIT 1;
  IF v_location_id IS NULL THEN
    INSERT INTO inventory_locations (name, code, description, is_active) VALUES ('Bodega Principal', 'MAIN', 'Ubicación principal', true) RETURNING id INTO v_location_id;
  END IF;

  SELECT id INTO v_category_id FROM inventory_categories WHERE name ILIKE '%compra%' OR name ILIKE '%general%' ORDER BY created_at ASC LIMIT 1;
  IF v_category_id IS NULL THEN
    INSERT INTO inventory_categories (name, description, code) VALUES ('Compras Generales', 'Productos comprados', 'PURCHASES') RETURNING id INTO v_category_id;
  END IF;

  v_quantity := COALESCE(NEW.purchase_quantity, 1);
  v_unit_cost := COALESCE(NEW.purchase_unit_cost, NEW.amount);

  SELECT id INTO v_inventory_item_id FROM inventory_items WHERE LOWER(TRIM(name)) = LOWER(TRIM(NEW.description)) LIMIT 1;
  IF v_inventory_item_id IS NULL THEN
    INSERT INTO inventory_items (name, description, category_id, unit_of_measure, minimum_stock, unit_cost, is_active)
    VALUES (NEW.description, 'Auto-creado desde costos', v_category_id, 'unidad', 1, v_unit_cost, true) RETURNING id INTO v_inventory_item_id;
  END IF;

  -- Crear movimiento de ENTRADA
  INSERT INTO inventory_movements (item_id, location_id, movement_type, quantity, unit_cost, total_cost, movement_date, reason, crane_id, cost_id, observations, created_by, status)
  VALUES (v_inventory_item_id, v_location_id, 'entry', v_quantity, v_unit_cost, NEW.amount, NEW.date, 'Compra desde módulo de costos', NEW.crane_id, NEW.id, COALESCE(NEW.notes, 'Sincronización automática'), NEW.created_by, 'active')
  RETURNING id INTO v_movement_id;

  UPDATE costs SET inventory_movement_id = v_movement_id WHERE id = NEW.id;

  -- Si es consumo inmediato Y tiene grúa seleccionada, crear movimiento de SALIDA
  IF NEW.immediate_consumption = true AND NEW.crane_id IS NOT NULL THEN
    INSERT INTO inventory_movements (
      item_id,
      location_id,
      movement_type,
      quantity,
      unit_cost,
      total_cost,
      movement_date,
      reason,
      crane_id,
      cost_id,
      observations,
      created_by,
      status
    )
    VALUES (
      v_inventory_item_id,
      v_location_id,
      'exit',                    -- Tipo SALIDA
      v_quantity,                -- Misma cantidad
      v_unit_cost,               -- Mismo costo unitario
      NEW.amount,                -- Mismo total
      NEW.date,                  -- Misma fecha
      'Consumo inmediato desde compra',  -- Razón específica
      NEW.crane_id,              -- Grúa destino
      NEW.id,                    -- Mismo cost_id para trazabilidad
      'Auto-generado: Consumo inmediato en grúa',
      NEW.created_by,
      'active'
    );

    RAISE NOTICE 'Movimiento de salida por consumo inmediato creado para grúa %', NEW.crane_id;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN 
  RAISE WARNING 'Error en sync_inventory_cost_to_movement: %', SQLERRM;
  RETURN NEW;
END;
$$", "-- Comentario explicativo
COMMENT ON FUNCTION public.sync_inventory_cost_to_movement() IS 
'Sincroniza automáticamente los costos de inventario con inventory_movements. Si immediate_consumption=true, crea entrada y salida inmediata a la grúa.'"]

["-- Función para sincronizar un ingreso específico a pago (casos retroactivos)
CREATE OR REPLACE FUNCTION sync_specific_income_to_payment(p_income_id UUID)
RETURNS jsonb AS $$
DECLARE
  v_income RECORD;
  v_payment_id UUID;
  v_result jsonb;
BEGIN
  -- Obtener el ingreso
  SELECT * INTO v_income FROM incomes WHERE id = p_income_id;

  -- Validar que el ingreso existe
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'El ingreso no existe'
    );
  END IF;

  -- Validar que tiene cliente y factura asociada
  IF v_income.invoice_id IS NULL OR v_income.client_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'El ingreso debe tener cliente y factura asociada'
    );
  END IF;

  -- Verificar si ya existe un payment similar (mismo cliente, monto y fecha)
  IF EXISTS (
    SELECT 1 FROM payments
    WHERE client_id = v_income.client_id
    AND amount = v_income.amount
    AND payment_date = v_income.income_date
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Ya existe un pago con estas características (mismo cliente, monto y fecha)'
    );
  END IF;

  -- Crear el payment
  INSERT INTO payments (
    client_id,
    amount,
    payment_date,
    payment_method,
    bank_reference,
    notes,
    status,
    remaining_amount
  ) VALUES (
    v_income.client_id,
    v_income.amount,
    v_income.income_date,
    v_income.payment_method,
    v_income.bank_reference,
    'Sincronizado desde ingreso: ' || v_income.description,
    'pending',
    v_income.amount
  )
  RETURNING id INTO v_payment_id;

  -- Aplicar a la factura usando la función existente
  SELECT apply_payment_manual(
    v_payment_id,
    jsonb_build_array(
      jsonb_build_object(
        'invoice_id', v_income.invoice_id,
        'amount', v_income.amount
      )
    )
  ) INTO v_result;

  -- Verificar si la aplicación fue exitosa
  IF v_result->>'success' = 'true' THEN
    RETURN jsonb_build_object(
      'success', true,
      'payment_id', v_payment_id,
      'message', 'Pago creado y aplicado exitosamente a la factura'
    );
  ELSE
    -- Si hubo error al aplicar, eliminar el payment creado
    DELETE FROM payments WHERE id = v_payment_id;
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Error al aplicar el pago a la factura: ' || COALESCE(v_result->>'error', 'Error desconocido')
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Error inesperado: ' || SQLERRM
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER"]

["-- Función para reparar aplicación de pago a factura (casos retroactivos)
CREATE OR REPLACE FUNCTION repair_payment_application(
  p_payment_id UUID,
  p_invoice_id UUID
)
RETURNS jsonb AS $$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
BEGIN
  -- Obtener payment
  SELECT * INTO v_payment FROM payments WHERE id = p_payment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment no encontrado');
  END IF;

  -- Obtener invoice
  SELECT * INTO v_invoice FROM invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invoice no encontrado');
  END IF;

  -- Verificar que no exista ya una aplicación
  IF EXISTS (
    SELECT 1 FROM payment_applications 
    WHERE payment_id = p_payment_id AND invoice_id = p_invoice_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Ya existe una aplicación para este pago e invoice');
  END IF;

  -- Aplicar usando la función existente
  RETURN apply_payment_manual(
    p_payment_id,
    jsonb_build_array(
      jsonb_build_object(
        'invoice_id', p_invoice_id,
        'amount', LEAST(v_payment.remaining_amount, v_invoice.remaining_amount)
      )
    )
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER"]

["-- Función para crear payment desde income existente
CREATE OR REPLACE FUNCTION create_payment_from_existing_income(p_income_id UUID)
RETURNS jsonb AS $$
DECLARE
  v_income RECORD;
  v_payment_id UUID;
  v_apply_result jsonb;
BEGIN
  -- Obtener datos del income
  SELECT * INTO v_income FROM incomes WHERE id = p_income_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Income no encontrado');
  END IF;

  -- Validar que tenga invoice_id asociado
  IF v_income.invoice_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Income no tiene factura asociada');
  END IF;

  -- Crear el payment
  INSERT INTO payments (
    client_id,
    amount,
    payment_date,
    payment_method,
    bank_reference,
    notes,
    status,
    applied_amount,
    remaining_amount
  ) VALUES (
    v_income.client_id,
    v_income.amount,
    v_income.income_date,
    v_income.payment_method,
    v_income.bank_reference,
    'Creado desde ingreso: ' || COALESCE(v_income.description, 'Sin descripción'),
    'pending',
    0,
    v_income.amount
  ) RETURNING id INTO v_payment_id;

  -- Aplicar el payment a la factura usando apply_payment_manual
  SELECT apply_payment_manual(
    v_payment_id,
    jsonb_build_array(
      jsonb_build_object(
        'invoice_id', v_income.invoice_id,
        'amount', v_income.amount
      )
    )
  ) INTO v_apply_result;

  -- Verificar resultado de la aplicación
  IF v_apply_result->>'status' != 'success' THEN
    -- Rollback: eliminar el payment creado
    DELETE FROM payments WHERE id = v_payment_id;
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Error al aplicar payment: ' || (v_apply_result->>'message')
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'message', 'Payment creado y aplicado exitosamente',
    'details', v_apply_result
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "-- Ejecutar la corrección para FACT-4033
SELECT create_payment_from_existing_income('e33f5689-619b-4e4b-a003-5859d7e0ffeb'::uuid)"]

