["-- ============================================================
-- CORRECCIÓN DEFINITIVA: Eliminar duplicación de actualización
-- de applied_amount en funciones de aplicación de pagos
-- ============================================================

-- Eliminar funciones existentes con todas sus variantes
DROP FUNCTION IF EXISTS public.apply_payment_fifo(UUID, UUID)", "DROP FUNCTION IF EXISTS public.apply_payment_fifo(UUID)", "DROP FUNCTION IF EXISTS public.apply_payment_manual(UUID, jsonb)", "-- 1. Crear apply_payment_fifo (sin actualización manual de applied_amount)
CREATE OR REPLACE FUNCTION public.apply_payment_fifo(p_payment_id UUID, p_client_id UUID DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  remaining_payment DECIMAL(10,2);
  amount_to_apply DECIMAL(10,2);
  applications_made INTEGER := 0;
  total_applied DECIMAL(10,2) := 0;
BEGIN
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pago no encontrado'; END IF;

  IF p_client_id IS NULL THEN p_client_id := payment_record.client_id; END IF;
  remaining_payment := payment_record.amount - payment_record.applied_amount;

  FOR invoice_record IN 
    SELECT * FROM public.invoices 
    WHERE client_id = p_client_id AND status IN ('sent', 'overdue', 'draft') AND remaining_amount > 0
    ORDER BY due_date ASC, created_at ASC
  LOOP
    EXIT WHEN remaining_payment <= 0;
    amount_to_apply := LEAST(remaining_payment, invoice_record.remaining_amount);

    INSERT INTO public.payment_applications (payment_id, invoice_id, applied_amount, application_method, created_by) 
    VALUES (p_payment_id, invoice_record.id, amount_to_apply, 'fifo', auth.uid());

    UPDATE public.invoices SET paid_amount = paid_amount + amount_to_apply, updated_at = NOW() WHERE id = invoice_record.id;

    remaining_payment := remaining_payment - amount_to_apply;
    total_applied := total_applied + amount_to_apply;
    applications_made := applications_made + 1;
  END LOOP;

  -- ✅ CRÍTICO: NO actualizar applied_amount aquí - el trigger lo hace automáticamente

  UPDATE public.invoices SET status = 'paid', payment_date = payment_record.payment_date
  WHERE client_id = p_client_id AND remaining_amount = 0 AND status != 'paid';

  RETURN jsonb_build_object(
    'success', true, 
    'applications_made', applications_made, 
    'total_applied', total_applied, 
    'remaining_payment', remaining_payment
  );
END;
$$", "-- 2. Crear apply_payment_manual (sin actualización manual de applied_amount)
CREATE OR REPLACE FUNCTION public.apply_payment_manual(p_payment_id UUID, p_applications jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $$
DECLARE
  payment_record RECORD;
  application RECORD;
  total_to_apply DECIMAL(10,2) := 0;
  total_applied DECIMAL(10,2) := 0;
  applications_made INTEGER := 0;
BEGIN
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pago no encontrado'; END IF;

  SELECT SUM((value->>'amount')::DECIMAL) INTO total_to_apply FROM jsonb_array_elements(p_applications);
  IF total_to_apply > (payment_record.amount - payment_record.applied_amount) THEN
    RAISE EXCEPTION 'El monto total a aplicar excede el monto disponible del pago';
  END IF;

  FOR application IN 
    SELECT (value->>'invoice_id')::UUID as invoice_id, (value->>'amount')::DECIMAL as amount
    FROM jsonb_array_elements(p_applications)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM public.invoices WHERE id = application.invoice_id AND client_id = payment_record.client_id AND remaining_amount >= application.amount) THEN
      RAISE EXCEPTION 'Factura inválida o monto excede el saldo pendiente';
    END IF;

    INSERT INTO public.payment_applications (payment_id, invoice_id, applied_amount, application_method, created_by) 
    VALUES (p_payment_id, application.invoice_id, application.amount, 'manual', auth.uid());

    UPDATE public.invoices SET paid_amount = paid_amount + application.amount, updated_at = NOW() WHERE id = application.invoice_id;

    total_applied := total_applied + application.amount;
    applications_made := applications_made + 1;
  END LOOP;

  -- ✅ CRÍTICO: NO actualizar applied_amount aquí - el trigger lo hace automáticamente

  UPDATE public.invoices SET status = 'paid', payment_date = payment_record.payment_date
  WHERE client_id = payment_record.client_id AND remaining_amount = 0 AND status != 'paid';

  RETURN jsonb_build_object(
    'success', true, 
    'applications_made', applications_made, 
    'total_applied', total_applied
  );
END;
$$", "-- 3. Ejecutar corrección inmediata de datos duplicados existentes
SELECT public.fix_applied_amount_duplications()", "COMMENT ON FUNCTION public.apply_payment_fifo IS 
'Aplica pagos usando FIFO. El trigger maintain_payment_consistency_trigger actualiza applied_amount automáticamente.'", "COMMENT ON FUNCTION public.apply_payment_manual IS 
'Aplica pagos manualmente. El trigger maintain_payment_consistency_trigger actualiza applied_amount automáticamente.'"]

["-- =====================================================
-- CORRECCIÓN COMPLETA DEL SISTEMA DE PAGOS
-- Reactiva triggers y corrige inconsistencias existentes
-- =====================================================

-- Paso 1: Eliminar triggers existentes si los hay (para recrearlos limpios)
DROP TRIGGER IF EXISTS maintain_payment_consistency_trigger ON payment_applications", "DROP TRIGGER IF EXISTS payment_applications_auto_update_invoice_status ON payment_applications", "-- Paso 2: Verificar que las funciones de trigger existan (recrearlas si es necesario)
CREATE OR REPLACE FUNCTION maintain_payment_consistency()
RETURNS TRIGGER AS $$
DECLARE
  v_total_applied DECIMAL(10,2);
  v_payment_amount DECIMAL(10,2);
  v_new_status payment_status;
BEGIN
  -- Calcular el total aplicado para este pago
  SELECT COALESCE(SUM(applied_amount), 0)
  INTO v_total_applied
  FROM payment_applications
  WHERE payment_id = COALESCE(NEW.payment_id, OLD.payment_id);

  -- Obtener el monto del pago
  SELECT amount INTO v_payment_amount
  FROM payments
  WHERE id = COALESCE(NEW.payment_id, OLD.payment_id);

  -- Determinar el nuevo estado
  IF v_total_applied = 0 THEN
    v_new_status := 'pending';
  ELSIF v_total_applied >= v_payment_amount THEN
    v_new_status := 'applied';
  ELSE
    v_new_status := 'partial';
  END IF;

  -- Actualizar el pago (solo campos no generados)
  UPDATE payments
  SET 
    applied_amount = v_total_applied,
    status = v_new_status,
    updated_at = now()
  WHERE id = COALESCE(NEW.payment_id, OLD.payment_id);

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public", "CREATE OR REPLACE FUNCTION update_invoice_status_from_payments()
RETURNS TRIGGER AS $$
DECLARE
  v_invoice_total DECIMAL(10,2);
  v_invoice_paid DECIMAL(10,2);
  v_new_status invoice_status;
  v_invoice_id UUID;
BEGIN
  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  -- Obtener el total de la factura
  SELECT total INTO v_invoice_total
  FROM invoices
  WHERE id = v_invoice_id;

  -- Calcular el total pagado para esta factura
  SELECT COALESCE(SUM(applied_amount), 0)
  INTO v_invoice_paid
  FROM payment_applications
  WHERE invoice_id = v_invoice_id;

  -- Determinar el nuevo estado de la factura
  IF v_invoice_paid = 0 THEN
    -- Mantener el estado actual si no hay pagos
    RETURN COALESCE(NEW, OLD);
  ELSIF v_invoice_paid >= v_invoice_total THEN
    v_new_status := 'paid';
  ELSE
    v_new_status := 'partial';
  END IF;

  -- Actualizar la factura (solo campos no generados)
  UPDATE invoices
  SET 
    paid_amount = v_invoice_paid,
    status = v_new_status,
    updated_at = now()
  WHERE id = v_invoice_id;

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public", "-- Paso 3: Crear los triggers
CREATE TRIGGER maintain_payment_consistency_trigger
  AFTER INSERT OR UPDATE OR DELETE ON payment_applications
  FOR EACH ROW
  EXECUTE FUNCTION maintain_payment_consistency()", "CREATE TRIGGER payment_applications_auto_update_invoice_status
  AFTER INSERT OR UPDATE OR DELETE ON payment_applications
  FOR EACH ROW
  EXECUTE FUNCTION update_invoice_status_from_payments()", "-- Paso 4: Función para corregir pagos inconsistentes existentes
CREATE OR REPLACE FUNCTION fix_existing_payment_inconsistencies()
RETURNS TABLE(
  payment_id UUID,
  old_applied_amount DECIMAL(10,2),
  new_applied_amount DECIMAL(10,2),
  old_status payment_status,
  new_status payment_status
) AS $$
DECLARE
  v_payment RECORD;
  v_total_applied DECIMAL(10,2);
  v_new_status payment_status;
BEGIN
  -- Iterar sobre todos los pagos
  FOR v_payment IN 
    SELECT p.id, p.amount, p.applied_amount as current_applied, p.status as current_status
    FROM payments p
  LOOP
    -- Calcular el verdadero total aplicado
    SELECT COALESCE(SUM(pa.applied_amount), 0)
    INTO v_total_applied
    FROM payment_applications pa
    WHERE pa.payment_id = v_payment.id;

    -- Determinar el estado correcto
    IF v_total_applied = 0 THEN
      v_new_status := 'pending';
    ELSIF v_total_applied >= v_payment.amount THEN
      v_new_status := 'applied';
    ELSE
      v_new_status := 'partial';
    END IF;

    -- Si hay diferencia, corregir
    IF v_total_applied != v_payment.current_applied OR v_new_status != v_payment.current_status THEN
      -- Guardar valores antiguos para el reporte
      payment_id := v_payment.id;
      old_applied_amount := v_payment.current_applied;
      new_applied_amount := v_total_applied;
      old_status := v_payment.current_status;
      new_status := v_new_status;

      -- Actualizar el pago
      UPDATE payments
      SET 
        applied_amount = v_total_applied,
        status = v_new_status,
        updated_at = now()
      WHERE id = v_payment.id;

      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public", "-- Paso 5: Función para corregir facturas inconsistentes existentes
CREATE OR REPLACE FUNCTION fix_existing_invoice_inconsistencies()
RETURNS TABLE(
  invoice_id UUID,
  old_paid_amount DECIMAL(10,2),
  new_paid_amount DECIMAL(10,2),
  old_status invoice_status,
  new_status invoice_status
) AS $$
DECLARE
  v_invoice RECORD;
  v_total_paid DECIMAL(10,2);
  v_new_status invoice_status;
BEGIN
  -- Iterar sobre todas las facturas
  FOR v_invoice IN 
    SELECT i.id, i.total, i.paid_amount as current_paid, i.status as current_status
    FROM invoices i
  LOOP
    -- Calcular el verdadero total pagado
    SELECT COALESCE(SUM(pa.applied_amount), 0)
    INTO v_total_paid
    FROM payment_applications pa
    WHERE pa.invoice_id = v_invoice.id;

    -- Determinar el estado correcto (solo si hay pagos)
    IF v_total_paid > 0 THEN
      IF v_total_paid >= v_invoice.total THEN
        v_new_status := 'paid';
      ELSE
        v_new_status := 'partial';
      END IF;
    ELSE
      -- Si no hay pagos, mantener el estado actual
      v_new_status := v_invoice.current_status;
    END IF;

    -- Si hay diferencia, corregir
    IF v_total_paid != v_invoice.current_paid OR (v_total_paid > 0 AND v_new_status != v_invoice.current_status) THEN
      -- Guardar valores antiguos para el reporte
      invoice_id := v_invoice.id;
      old_paid_amount := v_invoice.current_paid;
      new_paid_amount := v_total_paid;
      old_status := v_invoice.current_status;
      new_status := v_new_status;

      -- Actualizar la factura
      UPDATE invoices
      SET 
        paid_amount = v_total_paid,
        status = v_new_status,
        updated_at = now()
      WHERE id = v_invoice.id;

      RETURN NEXT;
    END IF;
  END LOOP;
END;
