    WHERE event_object_table = 'payment_applications'
      AND trigger_schema = 'public'
  )
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS %I ON payment_applications', r.trigger_name);
    RAISE NOTICE 'Eliminado trigger: %', r.trigger_name;
  END LOOP;
