    "observations": "Observaciones",
    "vehicle_brand": "Marca Vehículo",
    "vehicle_model": "Modelo Vehículo",
    "license_plate": "Patente"
  }';
  v_field_name TEXT;
  v_old_value TEXT;
  v_new_value TEXT;
  v_label TEXT;
BEGIN
  v_user_id := auth.uid();

  IF TG_OP = 'INSERT' THEN
    INSERT INTO service_change_history (service_id, service_folio, changed_by, change_type, field_name, new_value, change_summary)
    VALUES (NEW.id, NEW.folio, v_user_id, 'CREATE', 'servicio', NULL, 'Servicio creado');
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Comparar campos clave
    FOREACH v_field_name IN ARRAY ARRAY['value', 'purchase_order', 'quote_number', 'status',
      'operator_commission', 'client_covered_amount', 'excess_amount', 'insured_name',
      'origin', 'destination', 'observations', 'vehicle_brand', 'vehicle_model', 'license_plate'] LOOP

      EXECUTE format('SELECT ($1).%I::TEXT, ($2).%I::TEXT', v_field_name, v_field_name)
        INTO v_old_value, v_new_value USING OLD, NEW;

      IF v_old_value IS DISTINCT FROM v_new_value THEN
        v_label := COALESCE(v_field_labels->>v_field_name, v_field_name);

        INSERT INTO service_change_history (service_id, service_folio, changed_by, change_type, field_name, old_value, new_value, change_summary)
        VALUES (NEW.id, NEW.folio, v_user_id, 'UPDATE', v_field_name, v_old_value, v_new_value,
          format('%s: %s → %s', v_label, COALESCE(v_old_value, 'vacío'), COALESCE(v_new_value, 'vacío')));
      END IF;
    END LOOP;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- IMPORTANT:
    -- This trigger is configured as AFTER DELETE. At that point the service row is already gone,
    -- so inserting a history row with FK(service_id)->services(id) fails.
    -- We intentionally skip logging DELETE events to keep deletion working.
    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$function$"]

["-- =====================================================
-- Sincronización Triangular Definitiva
-- Costos ↔ Proveedores ↔ Bodega
-- =====================================================

-- ============ A. Mejorar trigger payment→cost ============
-- Reemplazar para que SOLO cree cost si NO tiene cost_id
CREATE OR REPLACE FUNCTION public.create_cost_from_supplier_payment()
RETURNS TRIGGER AS $$
DECLARE
  v_cost_id UUID;
  v_maintenance_cat_id UUID;
BEGIN
  -- Solo procesar en INSERT (no en UPDATE)
  IF TG_OP = 'INSERT' THEN
    -- Si ya viene con cost_id, fue creado desde un costo → no crear otro
    IF NEW.cost_id IS NOT NULL THEN
      RAISE NOTICE '[Payment→Cost] Payment % ya tiene cost_id %, skip', NEW.id, NEW.cost_id;
      RETURN NEW;
    END IF;

    -- Verificar si ya existe un cost con supplier_payment_id = NEW.id
    IF EXISTS (SELECT 1 FROM costs WHERE supplier_payment_id = NEW.id) THEN
      RAISE NOTICE '[Payment→Cost] Ya existe cost para payment %, skip', NEW.id;
      RETURN NEW;
    END IF;

    -- Obtener categoría de Mantenimiento como default
    SELECT id INTO v_maintenance_cat_id 
    FROM cost_categories 
    WHERE name = 'Mantenimiento' 
    LIMIT 1;

    -- Si no hay categoría, usar la primera disponible
    IF v_maintenance_cat_id IS NULL THEN
      SELECT id INTO v_maintenance_cat_id FROM cost_categories LIMIT 1;
    END IF;

    -- Crear el costo
    INSERT INTO costs (
      amount,
      category_id,
      date,
      description,
      supplier_id,
      supplier_payment_id,
      payment_date,
      created_by
    ) VALUES (
      NEW.amount,
      COALESCE(NEW.category::uuid, v_maintenance_cat_id),
      COALESCE(NEW.due_date, CURRENT_DATE),
      COALESCE(NEW.description, 'Pago a proveedor'),
      NEW.supplier_id,
      NEW.id,
      NEW.paid_date,
      NEW.created_by
    ) RETURNING id INTO v_cost_id;

    -- Vincular el payment con el cost creado
    UPDATE supplier_payments SET cost_id = v_cost_id WHERE id = NEW.id;

    RAISE NOTICE '[Payment→Cost] Cost % creado para payment %', v_cost_id, NEW.id;
  END IF;

  -- En UPDATE: si se marca como paid, actualizar payment_date en el cost vinculado
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM 'paid') AND NEW.cost_id IS NOT NULL THEN
      UPDATE costs 
      SET payment_date = COALESCE(NEW.paid_date, CURRENT_DATE)
      WHERE id = NEW.cost_id;
      RAISE NOTICE '[Payment→Cost] Updated payment_date on cost % from payment %', NEW.cost_id, NEW.id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "-- Recrear trigger para INSERT y UPDATE
DROP TRIGGER IF EXISTS create_cost_from_supplier_payment_trigger ON public.supplier_payments", "CREATE TRIGGER create_cost_from_supplier_payment_trigger
  AFTER INSERT OR UPDATE ON public.supplier_payments
  FOR EACH ROW
  EXECUTE FUNCTION public.create_cost_from_supplier_payment()", "-- ============ B. Nuevo trigger: sync cost UPDATE → payment ============
CREATE OR REPLACE FUNCTION public.sync_cost_update_to_payment()
RETURNS TRIGGER AS $$
BEGIN
  -- Solo sincronizar si tiene supplier_payment_id
  IF NEW.supplier_payment_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Verificar si cambió algo relevante
  IF (OLD.amount IS DISTINCT FROM NEW.amount) OR
     (OLD.supplier_id IS DISTINCT FROM NEW.supplier_id) OR
     (OLD.description IS DISTINCT FROM NEW.description) OR
     (OLD.payment_date IS DISTINCT FROM NEW.payment_date) THEN

    UPDATE supplier_payments SET
      amount = NEW.amount,
      supplier_id = COALESCE(NEW.supplier_id, supplier_id),
      description = NEW.description,
      paid_date = COALESCE(NEW.payment_date, paid_date),
      due_date = COALESCE(NEW.payment_date, NEW.date, due_date),
      updated_at = now()
    WHERE id = NEW.supplier_payment_id;

    RAISE NOTICE '[Cost→Payment UPDATE] Synced cost % → payment %', NEW.id, NEW.supplier_payment_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "DROP TRIGGER IF EXISTS sync_cost_update_to_payment_trigger ON public.costs", "CREATE TRIGGER sync_cost_update_to_payment_trigger
  AFTER UPDATE ON public.costs
  FOR EACH ROW
  EXECUTE FUNCTION public.sync_cost_update_to_payment()", "-- ============ C. Mejorar trigger DELETE cost → elimina payment + cancela inventory ============
CREATE OR REPLACE FUNCTION public.sync_cost_deletion_cascade()
RETURNS TRIGGER AS $$
BEGIN
  -- 1. Eliminar supplier_payment asociado (si existe)
  IF OLD.supplier_payment_id IS NOT NULL THEN
    DELETE FROM supplier_payments WHERE id = OLD.supplier_payment_id;
    RAISE NOTICE '[Cost DELETE] Deleted supplier_payment % for cost %', OLD.supplier_payment_id, OLD.id;
  END IF;

  -- También eliminar payments que referencien este cost via cost_id
  DELETE FROM supplier_payments WHERE cost_id = OLD.id;

  -- 2. Cancelar movimientos de inventario vinculados
  UPDATE inventory_movements 
  SET status = 'cancelled', 
      observations = COALESCE(observations, '') || ' [Cancelado por eliminación de costo ' || OLD.id || ']'
  WHERE cost_id = OLD.id AND status != 'cancelled';

  RAISE NOTICE '[Cost DELETE] Cascade completed for cost %', OLD.id;

  RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "-- Reemplazar el trigger de eliminación existente
DROP TRIGGER IF EXISTS sync_cost_supplier_payment_deletion ON public.costs", "DROP TRIGGER IF EXISTS sync_cost_deletion_cascade_trigger ON public.costs", "CREATE TRIGGER sync_cost_deletion_cascade_trigger
  BEFORE DELETE ON public.costs
  FOR EACH ROW
  EXECUTE FUNCTION public.sync_cost_deletion_cascade()", "-- ============ D. Nuevo trigger: DELETE payment → desvincula cost ============
CREATE OR REPLACE FUNCTION public.on_supplier_payment_delete()
RETURNS TRIGGER AS $$
BEGIN
  -- Desvincular el cost (no eliminarlo, puede tener otros usos)
  IF OLD.cost_id IS NOT NULL THEN
    UPDATE costs SET supplier_payment_id = NULL WHERE id = OLD.cost_id;
    RAISE NOTICE '[Payment DELETE] Unlinked cost % from payment %', OLD.cost_id, OLD.id;
  END IF;

  -- También desvincular costs que referencien este payment via supplier_payment_id
  UPDATE costs SET supplier_payment_id = NULL WHERE supplier_payment_id = OLD.id;

  RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "DROP TRIGGER IF EXISTS on_supplier_payment_delete_trigger ON public.supplier_payments", "CREATE TRIGGER on_supplier_payment_delete_trigger
  BEFORE DELETE ON public.supplier_payments
  FOR EACH ROW
  EXECUTE FUNCTION public.on_supplier_payment_delete()"]

["-- Create suppliers table if it doesn't exist
CREATE TABLE IF NOT EXISTS public.suppliers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    name TEXT NOT NULL,
    rut TEXT,
    email TEXT,
    phone TEXT,
    address TEXT,
    city TEXT,
    contact_name TEXT,
    category TEXT,
    payment_terms TEXT,
    notes TEXT,
    is_active BOOLEAN DEFAULT true,
    created_by UUID REFERENCES auth.users(id),
    updated_by UUID REFERENCES auth.users(id),
    metadata JSONB
)", "-- Add columns to suppliers if they don't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'suppliers' AND column_name = 'created_by') THEN
        ALTER TABLE public.suppliers ADD COLUMN created_by UUID REFERENCES auth.users(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'suppliers' AND column_name = 'updated_by') THEN
        ALTER TABLE public.suppliers ADD COLUMN updated_by UUID REFERENCES auth.users(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'suppliers' AND column_name = 'metadata') THEN
        ALTER TABLE public.suppliers ADD COLUMN metadata JSONB;
    END IF;
END $$", "-- Enable RLS for suppliers
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY", "-- Create policies for suppliers if they don't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Enable read access for all users') THEN
        CREATE POLICY "Enable read access for all users" ON public.suppliers FOR SELECT USING (true);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Enable insert access for authenticated users') THEN
        CREATE POLICY "Enable insert access for authenticated users" ON public.suppliers FOR INSERT WITH CHECK (auth.role() = 'authenticated');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Enable update access for authenticated users') THEN
        CREATE POLICY "Enable update access for authenticated users" ON public.suppliers FOR UPDATE USING (auth.role() = 'authenticated');
    END IF;
     IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'suppliers' AND policyname = 'Enable delete access for authenticated users') THEN
        CREATE POLICY "Enable delete access for authenticated users" ON public.suppliers FOR DELETE USING (auth.role() = 'authenticated');
    END IF;
END $$", "-- Create supplier_invoices table if it doesn't exist
CREATE TABLE IF NOT EXISTS public.supplier_invoices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    supplier_id UUID REFERENCES public.suppliers(id) ON DELETE SET NULL,
    invoice_number TEXT NOT NULL,
    issue_date TIMESTAMP WITH TIME ZONE,
    due_date TIMESTAMP WITH TIME ZONE,
    amount NUMERIC,
    tax_amount NUMERIC,
    net_amount NUMERIC,
    status TEXT,
    description TEXT,
    payment_terms NUMERIC,
    paid_amount NUMERIC DEFAULT 0,
    balance NUMERIC GENERATED ALWAYS AS (amount - COALESCE(paid_amount, 0)) STORED,
    currency TEXT,
    created_by UUID REFERENCES auth.users(id),
    updated_by UUID REFERENCES auth.users(id),
    metadata JSONB
)", "-- Add columns to supplier_invoices if they don't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'supplier_invoices' AND column_name = 'created_by') THEN
        ALTER TABLE public.supplier_invoices ADD COLUMN created_by UUID REFERENCES auth.users(id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'supplier_invoices' AND column_name = 'metadata') THEN
        ALTER TABLE public.supplier_invoices ADD COLUMN metadata JSONB;
    END IF;
END $$", "-- Add unique constraint for upsert
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'supplier_invoices_supplier_id_invoice_number_key') THEN
        ALTER TABLE public.supplier_invoices ADD CONSTRAINT supplier_invoices_supplier_id_invoice_number_key UNIQUE (supplier_id, invoice_number);
    END IF;
END $$", "-- Enable RLS for supplier_invoices
ALTER TABLE public.supplier_invoices ENABLE ROW LEVEL SECURITY", "-- Create policies for supplier_invoices if they don't exist
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'supplier_invoices' AND policyname = 'Enable read access for all users') THEN
        CREATE POLICY "Enable read access for all users" ON public.supplier_invoices FOR SELECT USING (true);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'supplier_invoices' AND policyname = 'Enable insert access for authenticated users') THEN
        CREATE POLICY "Enable insert access for authenticated users" ON public.supplier_invoices FOR INSERT WITH CHECK (auth.role() = 'authenticated');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'supplier_invoices' AND policyname = 'Enable update access for authenticated users') THEN
        CREATE POLICY "Enable update access for authenticated users" ON public.supplier_invoices FOR UPDATE USING (auth.role() = 'authenticated');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'supplier_invoices' AND policyname = 'Enable delete access for authenticated users') THEN
        CREATE POLICY "Enable delete access for authenticated users" ON public.supplier_invoices FOR DELETE USING (auth.role() = 'authenticated');
    END IF;
END $$"]

["CREATE OR REPLACE FUNCTION public.apply_payment_fifo(p_payment_id uuid, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  payment_record RECORD;
  invoice_record RECORD;
  remaining_payment DECIMAL(10,2);
  amount_to_apply DECIMAL(10,2);
  applications_made INTEGER := 0;
  total_applied DECIMAL(10,2) := 0;
BEGIN
  IF (SELECT role FROM public.profiles WHERE id = auth.uid()) NOT IN ('admin', 'operator') THEN
    RAISE EXCEPTION 'No tiene permisos para aplicar pagos';
  END IF;

  SELECT * INTO payment_record FROM public.payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pago no encontrado'; END IF;

  IF p_client_id IS NULL THEN p_client_id := payment_record.client_id; END IF;
  remaining_payment := payment_record.amount - payment_record.applied_amount;

  FOR invoice_record IN 
    SELECT * FROM public.invoices 
    WHERE client_id = p_client_id 
      AND status IN ('sent', 'overdue', 'draft') 
      AND remaining_amount > 0
      AND folio NOT LIKE 'HIST-%'
    ORDER BY due_date ASC, created_at ASC
  LOOP
    EXIT WHEN remaining_payment <= 0;
    amount_to_apply := LEAST(remaining_payment, invoice_record.remaining_amount);

    INSERT INTO public.payment_applications (payment_id, invoice_id, applied_amount, application_method, created_by) 
    VALUES (p_payment_id, invoice_record.id, amount_to_apply, 'fifo', auth.uid());

    UPDATE public.invoices SET paid_amount = paid_amount + amount_to_apply, updated_at = NOW() WHERE id = invoice_record.id;

    remaining_payment := remaining_payment - amount_to_apply;
    total_applied := total_applied + amount_to_apply;
    applications_made := applications_made + 1;
  END LOOP;

  UPDATE public.invoices SET status = 'paid', payment_date = payment_record.payment_date
  WHERE client_id = p_client_id AND remaining_amount = 0 AND status != 'paid' AND folio NOT LIKE 'HIST-%';

  RETURN jsonb_build_object(
    'success', true, 
    'applications_made', applications_made, 
    'total_applied', total_applied, 
    'remaining_payment', remaining_payment
  );
END;
$function$"]

["-- Fix trigger 1: auto_update_service_invoice_status
-- Only revert to 'completed' when current status IS 'invoiced' and folio is removed
CREATE OR REPLACE FUNCTION public.auto_update_service_invoice_status()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- When invoice_folio is added and status allows transition to invoiced
  IF NEW.invoice_folio IS NOT NULL AND NEW.invoice_folio != '' 
     AND (OLD.invoice_folio IS NULL OR OLD.invoice_folio = '') THEN
    IF NEW.status IN ('completed', 'failed') THEN
      NEW.status := 'invoiced';
    END IF;
  END IF;

  -- When invoice_folio is removed, only revert if currently invoiced
  IF (NEW.invoice_folio IS NULL OR NEW.invoice_folio = '') 
     AND (OLD.invoice_folio IS NOT NULL AND OLD.invoice_folio != '') THEN
    IF NEW.status = 'invoiced' THEN
      NEW.status := 'completed';
    END IF;
  END IF;

  RETURN NEW;
END;
$$", "-- Fix trigger 2: validate_service_invoice_consistency
-- Allow post-service states to coexist with or without invoice_folio
CREATE OR REPLACE FUNCTION public.validate_service_invoice_consistency()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- If status is 'invoiced' but no folio, revert to completed
  IF NEW.status = 'invoiced' AND (NEW.invoice_folio IS NULL OR NEW.invoice_folio = '') THEN
    NEW.status := 'completed';
  END IF;

  -- Do NOT force status to 'invoiced' just because invoice_folio exists.
  -- Post-service states (quoted, purchase_order_pending, with_purchase_order, completed, failed)
  -- are all valid even with an invoice_folio present.

  RETURN NEW;
END;
$$"]

["-- =====================================================
-- Fix: Sincronización payment_date cuando cost_id es NULL
-- =====================================================

-- 1. Vincular cost_id en payments huérfanos que ya tienen relación vía supplier_payment_id
UPDATE supplier_payments sp
SET cost_id = c.id
FROM costs c
WHERE c.supplier_payment_id = sp.id
  AND sp.cost_id IS NULL", "-- 2. Corregir payment_date del costo de Entel 52897759 (pagado hoy 2026-03-18)
UPDATE costs 
SET payment_date = '2026-03-18'
WHERE id = '0fa8df72-1c69-4a9c-ac86-5d93494437a2'", "-- 3. Mejorar trigger: buscar también por supplier_payment_id cuando cost_id es NULL
CREATE OR REPLACE FUNCTION public.create_cost_from_supplier_payment()
RETURNS TRIGGER AS $$
DECLARE
  v_cost_id UUID;
  v_maintenance_cat_id UUID;
BEGIN
  -- Solo procesar en INSERT (no en UPDATE)
  IF TG_OP = 'INSERT' THEN
    -- Si ya viene con cost_id, fue creado desde un costo → no crear otro
    IF NEW.cost_id IS NOT NULL THEN
      RAISE NOTICE '[Payment→Cost] Payment % ya tiene cost_id %, skip', NEW.id, NEW.cost_id;
      RETURN NEW;
    END IF;

    -- Verificar si ya existe un cost con supplier_payment_id = NEW.id
    IF EXISTS (SELECT 1 FROM costs WHERE supplier_payment_id = NEW.id) THEN
      RAISE NOTICE '[Payment→Cost] Ya existe cost para payment %, skip', NEW.id;
      RETURN NEW;
    END IF;

    -- Obtener categoría de Mantenimiento como default
    SELECT id INTO v_maintenance_cat_id 
    FROM cost_categories 
    WHERE name = 'Mantenimiento' 
    LIMIT 1;

    -- Si no hay categoría, usar la primera disponible
    IF v_maintenance_cat_id IS NULL THEN
      SELECT id INTO v_maintenance_cat_id FROM cost_categories LIMIT 1;
    END IF;

    -- Crear el costo
    INSERT INTO costs (
      amount,
      category_id,
      date,
      description,
      supplier_id,
      supplier_payment_id,
      payment_date,
      created_by
    ) VALUES (
      NEW.amount,
      COALESCE(NEW.category::uuid, v_maintenance_cat_id),
      COALESCE(NEW.due_date, CURRENT_DATE),
      COALESCE(NEW.description, 'Pago a proveedor'),
      NEW.supplier_id,
      NEW.id,
      NEW.paid_date,
      NEW.created_by
    ) RETURNING id INTO v_cost_id;

    -- Vincular el payment con el cost creado
    UPDATE supplier_payments SET cost_id = v_cost_id WHERE id = NEW.id;

    RAISE NOTICE '[Payment→Cost] Cost % creado para payment %', v_cost_id, NEW.id;
  END IF;

  -- En UPDATE: si se marca como paid, actualizar payment_date en el cost vinculado
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM 'paid') THEN
      -- Buscar cost_id directamente o por supplier_payment_id
      v_cost_id := NEW.cost_id;

      IF v_cost_id IS NULL THEN
        SELECT id INTO v_cost_id FROM costs WHERE supplier_payment_id = NEW.id LIMIT 1;
      END IF;

      IF v_cost_id IS NOT NULL THEN
        UPDATE costs 
        SET payment_date = COALESCE(NEW.paid_date, CURRENT_DATE)
        WHERE id = v_cost_id;

        -- También vincular cost_id si faltaba
        IF NEW.cost_id IS NULL THEN
          UPDATE supplier_payments SET cost_id = v_cost_id WHERE id = NEW.id;
        END IF;

        RAISE NOTICE '[Payment→Cost] Updated payment_date on cost % from payment %', v_cost_id, NEW.id;
      ELSE
        RAISE NOTICE '[Payment→Cost] No cost found for payment % (cost_id NULL, no supplier_payment_id match)', NEW.id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public", "-- Recrear trigger
DROP TRIGGER IF EXISTS create_cost_from_supplier_payment_trigger ON public.supplier_payments", "CREATE TRIGGER create_cost_from_supplier_payment_trigger
  AFTER INSERT OR UPDATE ON public.supplier_payments
  FOR EACH ROW
  EXECUTE FUNCTION public.create_cost_from_supplier_payment()"]

["-- Step 1: Fix trigger to resolve category by name lookup instead of UUID cast
CREATE OR REPLACE FUNCTION create_cost_from_supplier_payment()
RETURNS TRIGGER AS $$
DECLARE
  v_cost_id UUID;
  v_maintenance_cat_id UUID;
  v_resolved_cat_id UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.cost_id IS NOT NULL THEN
      RETURN NEW;
    END IF;

    IF EXISTS (SELECT 1 FROM costs WHERE supplier_payment_id = NEW.id) THEN
      RETURN NEW;
    END IF;

    -- Default category
    SELECT id INTO v_maintenance_cat_id 
    FROM cost_categories WHERE name = 'Mantenimiento' LIMIT 1;

    IF v_maintenance_cat_id IS NULL THEN
      SELECT id INTO v_maintenance_cat_id FROM cost_categories LIMIT 1;
    END IF;

    -- Resolve category: try UUID first, then name lookup
    v_resolved_cat_id := NULL;
    IF NEW.category IS NOT NULL AND NEW.category != '' THEN
      -- Try direct UUID cast
      BEGIN
        v_resolved_cat_id := NEW.category::uuid;
        -- Verify it exists
        IF NOT EXISTS (SELECT 1 FROM cost_categories WHERE id = v_resolved_cat_id) THEN
          v_resolved_cat_id := NULL;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_resolved_cat_id := NULL;
      END;

      -- If not a valid UUID, lookup by name
      IF v_resolved_cat_id IS NULL THEN
        SELECT id INTO v_resolved_cat_id 
        FROM cost_categories 
        WHERE lower(name) = lower(NEW.category) 
        LIMIT 1;
      END IF;
    END IF;

    INSERT INTO costs (
      amount, category_id, date, description,
      supplier_id, supplier_payment_id, payment_date, created_by
    ) VALUES (
      NEW.amount,
      COALESCE(v_resolved_cat_id, v_maintenance_cat_id),
      COALESCE(NEW.due_date, CURRENT_DATE),
      COALESCE(NEW.description, 'Pago a proveedor'),
      NEW.supplier_id, NEW.id, NEW.paid_date, NEW.created_by
    ) RETURNING id INTO v_cost_id;

    UPDATE supplier_payments SET cost_id = v_cost_id WHERE id = NEW.id;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'paid' AND (OLD.status IS DISTINCT FROM 'paid') THEN
      v_cost_id := NEW.cost_id;
      IF v_cost_id IS NULL THEN
        SELECT id INTO v_cost_id FROM costs WHERE supplier_payment_id = NEW.id LIMIT 1;
      END IF;
      IF v_cost_id IS NOT NULL THEN
        UPDATE costs SET payment_date = COALESCE(NEW.paid_date, CURRENT_DATE) WHERE id = v_cost_id;
        IF NEW.cost_id IS NULL THEN
          UPDATE supplier_payments SET cost_id = v_cost_id WHERE id = NEW.id;
        END IF;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "-- Step 2: Remove duplicate trigger
DROP TRIGGER IF EXISTS create_cost_from_supplier_payment_trigger ON supplier_payments", "-- Step 3: Fix check_supplier_invoice_duplicates to use inventory_suppliers
CREATE OR REPLACE FUNCTION check_supplier_invoice_duplicates(
  p_folio text,
  p_supplier_rut text DEFAULT NULL,
  p_amount numeric DEFAULT NULL,
  p_tolerance_percent numeric DEFAULT 5
)
RETURNS TABLE(
  id uuid,
  reference_number text,
  supplier_id uuid,
  supplier_name text,
  supplier_rut text,
  amount numeric,
  due_date date,
  created_at timestamp with time zone,
  match_type text
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    sp.id,
    sp.reference_number,
    sp.supplier_id,
    s.name AS supplier_name,
    s.rut AS supplier_rut,
    sp.amount,
    sp.due_date,
    sp.created_at,
    CASE
      WHEN sp.reference_number = p_folio THEN 'exact_folio'
      WHEN p_supplier_rut IS NOT NULL AND s.rut = p_supplier_rut AND p_amount IS NOT NULL 
           AND ABS(sp.amount - p_amount) <= (p_amount * p_tolerance_percent / 100) THEN 'similar'
    END AS match_type
  FROM supplier_payments sp
  JOIN inventory_suppliers s ON s.id = sp.supplier_id
  WHERE 
    sp.reference_number = p_folio
    OR (p_supplier_rut IS NOT NULL AND s.rut = p_supplier_rut AND p_amount IS NOT NULL 
        AND ABS(sp.amount - p_amount) <= (p_amount * p_tolerance_percent / 100))
  ORDER BY 
    CASE WHEN sp.reference_number = p_folio THEN 1 ELSE 2 END,
    sp.created_at DESC
  LIMIT 5;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER"]

["-- Step 4: Fix trigger to set paid_amount and use date as fallback for status
CREATE OR REPLACE FUNCTION create_supplier_payment_from_cost()
RETURNS TRIGGER AS $$
DECLARE
  v_payment_id UUID;
  v_status TEXT;
  v_paid_amount NUMERIC;
  v_paid_date DATE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Solo crear pago si hay supplier_id y no viene de un pago existente
    IF NEW.supplier_id IS NULL THEN
      RETURN NEW;
    END IF;

    IF NEW.supplier_payment_id IS NOT NULL THEN
      RETURN NEW;
    END IF;

    -- Evitar duplicados
    IF EXISTS (SELECT 1 FROM supplier_payments WHERE cost_id = NEW.id) THEN
      RETURN NEW;
    END IF;

    -- Determinar estado: si payment_date está seteado O si la fecha del costo es <= hoy → pagado
    IF (NEW.payment_date IS NOT NULL AND NEW.payment_date <= CURRENT_DATE) THEN
      v_status := 'paid';
      v_paid_amount := NEW.amount;
      v_paid_date := NEW.payment_date;
    ELSIF (NEW.date <= CURRENT_DATE AND NEW.payment_date IS NULL) THEN
      -- Costo sin payment_date pero con fecha pasada: pendiente (el usuario no marcó "pagado")
      v_status := 'pending';
      v_paid_amount := 0;
      v_paid_date := NULL;
    ELSE
      v_status := 'pending';
      v_paid_amount := 0;
      v_paid_date := NULL;
    END IF;

    INSERT INTO supplier_payments (
      supplier_id, amount, paid_amount, description, 
      due_date, status, paid_date, cost_id, created_by,
      category
    ) VALUES (
      NEW.supplier_id,
      NEW.amount,
      v_paid_amount,
      COALESCE(NEW.description, 'Gasto registrado'),
      COALESCE(NEW.date, CURRENT_DATE),
      v_status,
      v_paid_date,
      NEW.id,
      NEW.created_by,
      NEW.subcategory
    ) RETURNING id INTO v_payment_id;

    -- Vincular el pago al costo
    UPDATE costs SET supplier_payment_id = v_payment_id WHERE id = NEW.id;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Propagar cambios al pago existente
    IF NEW.supplier_payment_id IS NOT NULL OR OLD.supplier_payment_id IS NOT NULL THEN
      DECLARE
        v_sp_id UUID := COALESCE(NEW.supplier_payment_id, OLD.supplier_payment_id);
      BEGIN
        -- Determinar nuevo estado
        IF (NEW.payment_date IS NOT NULL AND NEW.payment_date <= CURRENT_DATE) THEN
          v_status := 'paid';
          v_paid_amount := NEW.amount;
          v_paid_date := NEW.payment_date;
        ELSE
          -- Mantener estado actual del pago si no hay payment_date
          SELECT status, paid_amount, paid_date INTO v_status, v_paid_amount, v_paid_date
          FROM supplier_payments WHERE id = v_sp_id;
        END IF;

        UPDATE supplier_payments SET
          amount = NEW.amount,
          paid_amount = CASE WHEN v_status = 'paid' THEN NEW.amount ELSE paid_amount END,
          description = COALESCE(NEW.description, description),
          due_date = COALESCE(NEW.date, due_date),
          paid_date = CASE WHEN v_status = 'paid' THEN v_paid_date ELSE paid_date END,
          status = v_status,
          supplier_id = COALESCE(NEW.supplier_id, supplier_id)
        WHERE id = v_sp_id;
      END;
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    -- Eliminar pago asociado
    IF OLD.supplier_payment_id IS NOT NULL THEN
      DELETE FROM supplier_payments WHERE id = OLD.supplier_payment_id;
    END IF;
    DELETE FROM supplier_payments WHERE cost_id = OLD.id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER", "-- Asegurar que el trigger existe
DROP TRIGGER IF EXISTS create_supplier_payment_from_cost ON costs", "CREATE TRIGGER create_supplier_payment_from_cost
  AFTER INSERT OR UPDATE OR DELETE ON costs
  FOR EACH ROW
  EXECUTE FUNCTION create_supplier_payment_from_cost()", "-- Step 5: Fix existing orphaned records - pagos creados desde costos que deberían estar pagados
UPDATE supplier_payments sp
SET 
  status = 'paid',
  paid_amount = sp.amount,
  paid_date = c.payment_date
FROM costs c
WHERE sp.cost_id = c.id
  AND c.payment_date IS NOT NULL
  AND c.payment_date <= CURRENT_DATE
  AND sp.status = 'pending'"]

["-- Backfill: crear supplier_payments para costos existentes sin pago asociado
DO $$
DECLARE
  r RECORD;
  v_payment_id UUID;
  v_status TEXT;
  v_paid_amount NUMERIC;
  v_paid_date DATE;
  v_count INT := 0;
BEGIN
  FOR r IN
    SELECT c.*
    FROM costs c
    WHERE c.supplier_id IS NOT NULL
      AND c.supplier_payment_id IS NULL
      AND NOT EXISTS (
        SELECT 1 FROM supplier_payments sp WHERE sp.cost_id = c.id
      )
  LOOP
    IF r.payment_date IS NOT NULL AND r.payment_date <= CURRENT_DATE THEN
      v_status := 'paid';
      v_paid_amount := r.amount;
      v_paid_date := r.payment_date;
    ELSE
      v_status := 'pending';
      v_paid_amount := 0;
      v_paid_date := NULL;
    END IF;

    INSERT INTO supplier_payments (
      supplier_id, amount, paid_amount, description,
      due_date, status, paid_date, cost_id, created_by, category
    ) VALUES (
      r.supplier_id, r.amount, v_paid_amount,
      COALESCE(r.description, 'Gasto registrado'),
      COALESCE(r.date, CURRENT_DATE),
      v_status, v_paid_date, r.id, r.created_by, r.subcategory
    ) RETURNING id INTO v_payment_id;

    UPDATE costs SET supplier_payment_id = v_payment_id WHERE id = r.id;
    v_count := v_count + 1;
  END LOOP;

  RAISE NOTICE 'Backfill completado: % pagos creados', v_count;
END $$"]

