  old_value TEXT,
  new_value TEXT,
  change_summary TEXT,
  change_context TEXT
)", "CREATE INDEX IF NOT EXISTS idx_cch_cost_id ON public.cost_change_history(cost_id)", "CREATE INDEX IF NOT EXISTS idx_cch_changed_at ON public.cost_change_history(changed_at DESC)", "ALTER TABLE public.cost_change_history ENABLE ROW LEVEL SECURITY", "DROP POLICY IF EXISTS cch_select_authenticated ON public.cost_change_history", "CREATE POLICY cch_select_authenticated ON public.cost_change_history
  FOR SELECT TO authenticated USING (true)", "DROP POLICY IF EXISTS cch_no_direct_insert ON public.cost_change_history", "CREATE POLICY cch_no_direct_insert ON public.cost_change_history
  FOR INSERT TO authenticated WITH CHECK (false)", "-- =========================================================
