)", "CREATE INDEX IF NOT EXISTS idx_imch_movement_id ON public.inventory_movement_change_history(movement_id)", "CREATE INDEX IF NOT EXISTS idx_imch_changed_at ON public.inventory_movement_change_history(changed_at DESC)", "ALTER TABLE public.inventory_movement_change_history ENABLE ROW LEVEL SECURITY", "DROP POLICY IF EXISTS imch_select_authenticated ON public.inventory_movement_change_history", "CREATE POLICY imch_select_authenticated ON public.inventory_movement_change_history
  FOR SELECT TO authenticated USING (true)", "DROP POLICY IF EXISTS imch_no_direct_insert ON public.inventory_movement_change_history", "CREATE POLICY imch_no_direct_insert ON public.inventory_movement_change_history
  FOR INSERT TO authenticated WITH CHECK (false)", "-- =========================================================
