    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$", "DROP TRIGGER IF EXISTS trigger_track_inventory_movement_changes ON public.inventory_movements", "CREATE TRIGGER trigger_track_inventory_movement_changes
AFTER INSERT OR UPDATE OR DELETE ON public.inventory_movements
FOR EACH ROW EXECUTE FUNCTION public.track_inventory_movement_changes()", "-- =========================================================
