  schedule_hour integer NOT NULL DEFAULT 3 CHECK (schedule_hour >= 0 AND schedule_hour <= 23),
  signed_url_days integer NOT NULL DEFAULT 7 CHECK (signed_url_days BETWEEN 1 AND 30),
  last_sent_at timestamptz,
