["-- Permite asignar o desasignar un cliente a un usuario desde acciones administrativas
CREATE OR REPLACE FUNCTION public.assign_user_client(
  target_user_id uuid,
  target_client_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin_user_safe() THEN
    RAISE EXCEPTION 'Only admins can assign clients to users';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = target_user_id
  ) THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF target_client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.clients
    WHERE id = target_client_id
  ) THEN
    RAISE EXCEPTION 'Client not found';
  END IF;

  UPDATE public.profiles
  SET
    client_id = target_client_id,
    updated_at = now()
  WHERE id = target_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.assign_user_client(uuid, uuid) TO authenticated;
"]

["-- 1. RENOMBRAR subcategoría en cost_subcategories
UPDATE public.cost_subcategories cs
SET
  name       = 'Trámite Rev. Técnica (cliente)',
  updated_at = now()
FROM public.cost_categories cc
WHERE cs.category_id = cc.id
  AND cc.name        = 'Gastos de Servicios'
  AND cs.name        = 'Pago Revisión Técnica';

-- 2. RENOMBRAR categoría "Seguros" → "Seguros y Permisos"
UPDATE public.cost_categories
SET
  name        = 'Seguros y Permisos',
  description = 'Pólizas de seguro, permisos de circulación y revisiones técnicas de la flota'
WHERE name    = 'Seguros';

-- 3. RENOMBRAR categoría "Combustible" → "Combustible equipos aux."
UPDATE public.cost_categories
SET
  name        = 'Combustible equipos aux.',
  description = 'Combustible para generadores, herramientas y equipos auxiliares. NO incluye combustible de vehículos en servicio (eso va en Gastos de Servicios).'
WHERE name    = 'Combustible';

-- 4. INSERTAR subcategorías nuevas
DO $$
DECLARE
  v_cat_id uuid;
BEGIN

  SELECT id INTO v_cat_id FROM public.cost_categories WHERE name = 'Seguros y Permisos' LIMIT 1;
  IF v_cat_id IS NOT NULL THEN
    INSERT INTO public.cost_subcategories (category_id, name, display_order, is_active, requires_supplier, requires_document)
    SELECT v_cat_id, sub.name, sub.ord, true, sub.req_sup, sub.req_doc
    FROM (VALUES
      ('SOAP',                       1, true,  true),
      ('Seguro de carga',            2, true,  true),
      ('Seguro de responsabilidad',  3, true,  true),
      ('Permiso de circulación',     4, false, true),
      ('Revisión técnica (flota)',   5, false, true),
      ('Otros',                      6, false, false)
    ) AS sub(name, ord, req_sup, req_doc)
    WHERE NOT EXISTS (SELECT 1 FROM public.cost_subcategories WHERE category_id = v_cat_id AND name = sub.name);
  END IF;

  SELECT id INTO v_cat_id FROM public.cost_categories WHERE name = 'Salarios' LIMIT 1;
  IF v_cat_id IS NOT NULL THEN
    INSERT INTO public.cost_subcategories (category_id, name, display_order, is_active, requires_operator)
    SELECT v_cat_id, sub.name, sub.ord, true, sub.req_op
    FROM (VALUES
      ('Remuneración mensual',    1, false),
      ('Horas extra',             2, true),
      ('Bono producción',         3, true),
      ('Anticipo de sueldo',      4, true),
      ('Liquidación / finiquito', 5, false),
      ('Otros',                   6, false)
    ) AS sub(name, ord, req_op)
    WHERE NOT EXISTS (SELECT 1 FROM public.cost_subcategories WHERE category_id = v_cat_id AND name = sub.name);
  END IF;

  SELECT id INTO v_cat_id FROM public.cost_categories WHERE name = 'Administrativos' LIMIT 1;
  IF v_cat_id IS NOT NULL THEN
    INSERT INTO public.cost_subcategories (category_id, name, display_order, is_active, requires_supplier, requires_document)
    SELECT v_cat_id, sub.name, sub.ord, true, sub.req_sup, sub.req_doc
    FROM (VALUES
      ('Arriendo oficina / bodega', 1, true,  true),
      ('Software y suscripciones',  2, true,  true),
      ('Servicios básicos',         3, true,  true),
      ('Útiles y materiales',       4, false, false),
      ('Comunicaciones',            5, true,  false),
      ('Contabilidad / asesoría',   6, true,  true),
      ('Otros',                     7, false, false)
    ) AS sub(name, ord, req_sup, req_doc)
    WHERE NOT EXISTS (SELECT 1 FROM public.cost_subcategories WHERE category_id = v_cat_id AND name = sub.name);
  END IF;

  SELECT id INTO v_cat_id FROM public.cost_categories WHERE name = 'Impuestos' LIMIT 1;
  IF v_cat_id IS NOT NULL THEN
    INSERT INTO public.cost_subcategories (category_id, name, display_order, is_active, requires_document)
    SELECT v_cat_id, sub.name, sub.ord, true, sub.req_doc
    FROM (VALUES
      ('Patente municipal',      1, true),
      ('Multa de tránsito',      2, true),
      ('IVA no recuperable',     3, true),
      ('Impuesto de timbre',     4, true),
      ('Contribuciones',         5, true),
      ('Otros tributos',         6, false)
    ) AS sub(name, ord, req_doc)
    WHERE NOT EXISTS (SELECT 1 FROM public.cost_subcategories WHERE category_id = v_cat_id AND name = sub.name);
  END IF;

  SELECT id INTO v_cat_id FROM public.cost_categories WHERE name = 'Combustible equipos aux.' LIMIT 1;
  IF v_cat_id IS NOT NULL THEN
    INSERT INTO public.cost_subcategories (category_id, name, display_order, is_active)
    SELECT v_cat_id, sub.name, sub.ord, true
    FROM (VALUES
      ('Generador',         1),
      ('Herramientas',      2),
      ('Equipo de trabajo', 3),
      ('Otros',             4)
    ) AS sub(name, ord)
    WHERE NOT EXISTS (SELECT 1 FROM public.cost_subcategories WHERE category_id = v_cat_id AND name = sub.name);
  END IF;

END $$;

-- 5. CONFIGURAR default_cost_center_id
DO $$
DECLARE
  v_center_oper_serv  uuid;
  v_center_mant       uuid;
  v_center_oper_gru   uuid;
  v_center_remu       uuid;
  v_center_admin      uuid;
  v_center_iptos      uuid;
BEGIN
  SELECT id INTO v_center_oper_serv FROM public.cost_centers WHERE code = 'OPER-SERV' LIMIT 1;
  SELECT id INTO v_center_mant      FROM public.cost_centers WHERE code = 'MANT'      LIMIT 1;
  SELECT id INTO v_center_oper_gru  FROM public.cost_centers WHERE code = 'OPER-GRU'  LIMIT 1;
  SELECT id INTO v_center_remu      FROM public.cost_centers WHERE code = 'REMU'      LIMIT 1;
  SELECT id INTO v_center_admin     FROM public.cost_centers WHERE code = 'ADMIN'     LIMIT 1;
  SELECT id INTO v_center_iptos     FROM public.cost_centers WHERE code = 'IPTOS'     LIMIT 1;

  IF v_center_oper_serv IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_oper_serv
    WHERE name = 'Gastos de Servicios' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_oper_serv);
  END IF;

  IF v_center_mant IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_mant
    WHERE name = 'Mantenimiento' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_mant);
  END IF;

  IF v_center_oper_gru IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_oper_gru
    WHERE name = 'Seguros y Permisos' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_oper_gru);
  END IF;

  IF v_center_remu IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_remu
    WHERE name = 'Salarios' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_remu);
  END IF;

  IF v_center_admin IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_admin
    WHERE name = 'Administrativos' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_admin);
  END IF;

  IF v_center_iptos IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_iptos
    WHERE name = 'Impuestos' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_iptos);
  ELSIF v_center_admin IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_admin
    WHERE name = 'Impuestos' AND default_cost_center_id IS NULL;
  END IF;

  IF v_center_mant IS NOT NULL THEN
    UPDATE public.cost_categories SET default_cost_center_id = v_center_mant
    WHERE name = 'Combustible equipos aux.' AND (default_cost_center_id IS NULL OR default_cost_center_id != v_center_mant);
  END IF;

END $$;"]

["CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = 'public'
AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.id) THEN
    RAISE NOTICE 'Profile already exists for user %', NEW.id;
    RETURN NEW;
  END IF;

  IF EXISTS (SELECT 1 FROM public.profiles WHERE email = NEW.email) THEN
    RAISE NOTICE 'Profile with email % already exists', NEW.email;
    RETURN NEW;
  END IF;

  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(
      NEW.raw_user_meta_data->>'full_name',
      NEW.raw_user_meta_data->>'name',
      NEW.email
    ),
    'viewer'
  );

  RETURN NEW;
END;
$$;"]

["
CREATE TYPE crane_status AS ENUM (
  'active',
  'inactive',
  'sold',
  'written_off'
);

ALTER TABLE public.cranes
  ADD COLUMN IF NOT EXISTS status crane_status NOT NULL DEFAULT 'active';

UPDATE public.cranes
  SET status = CASE
    WHEN is_active = true  THEN 'active'::crane_status
    WHEN is_active = false THEN 'inactive'::crane_status
  END;

CREATE INDEX IF NOT EXISTS idx_cranes_status ON public.cranes(status);
